{
  "name": "CyberCop: Robot Transfomer",
  "description": "An action-packed platformer where you play as a transforming police robot. Switch between robot mode for tactical shooting and car mode for high-speed ramming to neutralize 5 evil bots across 20 challenging levels.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE'
}

export enum PlayerMode {
  ROBOT = 'ROBOT',
  CAR = 'CAR'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short cyberpunk mission briefing for Level ${level} of a robot police officer game. 
      The goal is always to destroy 5 evil robots. 
      Provide a cool title, threat level, and a 2-sentence description.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini failed, using fallback briefing", error);
    return {
      level,
      title: `Sector ${level} Purge`,
      description: `Target verified in the neon district. Sweep the area and eliminate all 5 rogue units.`,
      threatLevel: "High",
      enemyType: "Rogue Sentinels"
    };
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    startLevel(1);
  };

  const handleNextLevel = () => {
    const nextLvl = level + 1;
    if (nextLvl > 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      startLevel(nextLvl);
    }
  };

  const handleLevelComplete = () => {
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none">
      {gameState === GameState.MENU && <MainMenu onStart={handleStartGame} />}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {gameState === GameState.PLAYING && (
        <GameView 
          level={level} 
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/80 flex flex-col items-center justify-center z-50">
          <h2 className="text-4xl text-cyan-400 mb-4 animate-pulse">SECTOR SECURED</h2>
          <p className="text-xl text-white mb-8">All 5 hostiles eliminated.</p>
          <button 
            onClick={handleNextLevel}
            className="px-8 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-bold rounded-sm border-b-4 border-cyan-800 transition-all active:translate-y-1"
          >
            NEXT LEVEL
          </button>
        </div>
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => setGameState(GameState.MENU)} />
      )}
    </div>
  );
};

export default App;

import React from 'react';
