export default Briefing;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy } from '../types';

interface GameViewProps {
  level: number;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 8;
const JUMP_FORCE = -10;

const GameView: React.FC<GameViewProps> = ({ level, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [kills, setKills] = useState(0);

  // Use refs for engine values to avoid React re-render overhead in loop
  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1, // 1 for right, -1 for left
      grounded: false,
      lastShot: 0,
      invulnerable: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0
  });

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    setHealth(100);
    setKills(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Spawn 5 enemies
    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      enemies.push({
        id: i,
        pos: { x: 600 + i * 400 + Math.random() * 100, y: 300 },
        vel: { x: (Math.random() - 0.5) * 2, y: 0 },
        width: 32,
        height: 48,
        health: 50 + level * 5,
        maxHealth: 50 + level * 5,
        isDead: false,
        type: 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyT') {
        setPlayerMode(prev => prev === PlayerMode.ROBOT ? PlayerMode.CAR : PlayerMode.ROBOT);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets } = e;
      e.frame++;

      // Player Movement Logic
      const speed = playerMode === PlayerMode.ROBOT ? PLAYER_SPEED_ROBOT : PLAYER_SPEED_CAR;
      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && playerMode === PlayerMode.ROBOT) {
        player.vel.y = JUMP_FORCE;
        player.grounded = false;
      }

      // Gravity & Collision (floor)
      player.vel.y += GRAVITY;
      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      if (player.pos.y > 350) {
        player.pos.y = 350;
        player.vel.y = 0;
        player.grounded = true;
      }

      // Bounds
      if (player.pos.x < 0) player.pos.x = 0;

      // Shooting Logic
      if (keys['Space'] && playerMode === PlayerMode.ROBOT && e.frame - player.lastShot > 15) {
        bullets.push({
          pos: { x: player.pos.x + (player.facing === 1 ? player.width : 0), y: player.pos.y + 15 },
          vel: { x: player.facing * 12, y: 0 },
          width: 8,
          height: 4,
          owner: 'player',
          health: 1,
          maxHealth: 1
        });
        player.lastShot = e.frame;
      }

      // Bullet Update
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        // Screen bounds for bullets
        if (Math.abs(b.pos.x - player.pos.x) > 1000) {
          bullets.splice(i, 1);
        }
      }

      // Enemies AI
      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        // Basic patrol
        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        // Enemy Shooting
        if (Math.abs(enemy.pos.x - player.pos.x) < 400 && e.frame - enemy.lastShot > 60 + Math.random() * 60) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          bullets.push({
            pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
            vel: { x: dir * 5, y: 0 },
            width: 8,
            height: 4,
            owner: 'enemy',
            health: 1,
            maxHealth: 1
          });
          enemy.lastShot = e.frame;
        }

        // Bullet Hit detection
        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        // Player Collision (Damaging or Ramming)
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {

          if (playerMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            // Ramming Kill
            enemy.isDead = true;
            enemy.health = 0;
          } else if (player.invulnerable <= 0) {
            // Take damage
            setHealth(h => {
                const newH = Math.max(0, h - 10);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      // Player take bullet damage
      bullets.forEach((b, bIdx) => {
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + player.width && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + player.height && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const newH = Math.max(0, h - 5);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      // Camera
      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, cameraX } = e;

      // Clear
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Background Grid/City
      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      // Floor
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, 350 + 48, CANVAS_WIDTH, CANVAS_HEIGHT - 350);
      ctx.strokeStyle = '#00f3ff';
      ctx.beginPath();
      ctx.moveTo(0, 350 + 48);
      ctx.lineTo(CANVAS_WIDTH, 350 + 48);
      ctx.stroke();

      // Draw Enemies
      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        // Body
        ctx.fillStyle = '#ff0055';
        ctx.fillRect(0, 0, enemy.width, enemy.height);

        // Health bar
        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -10, enemy.width, 4);
        ctx.fillStyle = '#ff0000';
        ctx.fillRect(0, -10, (enemy.health / enemy.maxHealth) * enemy.width, 4);

        // Eyes
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(5, 10, 5, 5);
        ctx.fillRect(22, 10, 5, 5);
        ctx.restore();
      });

      // Draw Player
      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (playerMode === PlayerMode.ROBOT) {
        // Robot Render
        ctx.fillStyle = '#00f3ff';
        ctx.fillRect(0, 0, 32, 48); // Body
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16); // Head/Visor
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4); // Visor glow
      } else {
        // Car Render
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 24, 48, 24); // Body
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 40, 8, 8); // Wheels
        ctx.fillRect(35, 40, 8, 8);
        // Siren
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, 16, 16, 8);
      }
      ctx.restore();

      // Draw Bullets
      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? '#00f3ff' : '#ff0055';
        ctx.shadowBlur = 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [playerMode, resetLevel, onDie, onWin, level]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 'PATROL UNIT';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 'text-blue-500';

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      {/* HUD */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1">Integrity</div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${health}%` }}
              ></div>
            </div>
          </div>
          <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
            MODE: {modeName}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400' : 'bg-gray-800 border-gray-700'}`}></div>
              ))}
            </div>
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      {/* Control Hints Overlay */}
      <div className="absolute bottom-4 left-4 text-xs text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded">
        <div>[WASD/ARROWS] Move</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[T] Transform</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

export default GameView;

import React from 'react';

interface GameOverProps {
  level: number;
  onRetry: () => void;
  onMenu: () => void;
}

const GameOver: React.FC<GameOverProps> = ({ level, onRetry, onMenu }) => {
  return (
    <div className="fixed inset-0 bg-red-950/90 flex flex-col items-center justify-center z-50 p-6">
      <div className="max-w-md w-full text-center space-y-8 animate-in fade-in zoom-in duration-300">
        <h1 className="text-6xl font-black text-white italic tracking-tighter drop-shadow-lg">
          UNIT <span className="text-red-500">OFFLINE</span>
        </h1>

        <div className="p-6 bg-black/40 border-y border-red-500">
          <p className="text-red-200 text-lg uppercase tracking-widest mb-2">Operational Failure</p>
          <p className="text-white font-mono">Mission aborted in Sector {level}.</p>
        </div>

        <div className="flex flex-col gap-4">
          <button 
            onClick={onRetry}
            className="py-4 bg-white text-red-900 font-black text-xl hover:bg-red-100 transition-colors"
          >
            REBOOT & RETRY
          </button>
          <button 
            onClick={onMenu}
            className="py-2 text-red-300 font-bold hover:text-white transition-colors uppercase text-sm"
          >
            Return to HQ
          </button>
        </div>
      </div>
    </div>
  );
};

export default GameOver;

import React from 'react';

interface VictoryProps {
  onMenu: () => void;
}

const Victory: React.FC<VictoryProps> = ({ onMenu }) => {
  return (
    <div className="fixed inset-0 bg-gradient-to-b from-blue-900 to-black flex flex-col items-center justify-center z-50 p-6">
      <div className="max-w-2xl text-center space-y-8">
        <div className="relative inline-block">
          <h1 className="text-7xl font-black text-white uppercase italic tracking-tighter">
            PEACE <span className="text-cyan-400">RESTORED</span>
          </h1>
          <div className="absolute -top-6 -right-6 animate-bounce">
            <span className="text-4xl">⭐</span>
          </div>
        </div>

        <div className="space-y-4">
          <p className="text-cyan-200 text-2xl tracking-widest uppercase font-bold">The City is Safe.</p>
          <p className="text-gray-400 max-w-lg mx-auto">
            You have successfully neutralized all rogue elements across all 20 sectors. 
            Unit 77 is commended for extreme efficiency and bravery in the line of duty.
          </p>
        </div>

        <div className="bg-cyan-900/30 p-8 border border-cyan-500/50 rounded-lg backdrop-blur-md">
          <div className="text-6xl mb-4">👮‍♂️🤖🚔</div>
