            </div>
            <div className="flex flex-col items-center">
              <span className="bg-gray-800 px-2 py-1 rounded mb-1 border border-gray-700">SPACE</span>
              <span>ATTACK</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MainMenu;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP'
}

export enum PlayerMode {
  ROBOT = 'ROBOT',
  CAR = 'CAR',
  JET = 'JET'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 8;
const PLAYER_SPEED_JET = 7;
const JUMP_FORCE = -10;

const GameView: React.FC<GameViewProps> = ({ level, upgrades, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0
  });

  const resetLevel = useCallback(() => {
    const e = engineRef.current;

    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setPlayerMode(PlayerMode.ROBOT);

    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      const isTitan = i === 4;
      const baseHealth = 50 + level * 10;
      enemies.push({
        id: i,
        pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
        vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
        width: isTitan ? 64 : 32,
        height: isTitan ? 96 : 48,
        health: isTitan ? baseHealth * 6 : baseHealth,
        maxHealth: isTitan ? baseHealth * 6 : baseHealth,
        isDead: false,
        type: isTitan ? 'titan' : 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyT') {
        setPlayerMode(prev => {
          if (prev === PlayerMode.ROBOT) return PlayerMode.CAR;
          if (prev === PlayerMode.CAR) return PlayerMode.JET;
          return PlayerMode.ROBOT;
        });
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets } = e;
      e.frame++;

      // Physics based on mode
      if (playerMode === PlayerMode.JET) {
        // Jet Flight Physics
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }

        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -PLAYER_SPEED_JET;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = PLAYER_SPEED_JET;
        } else {
          player.vel.y *= 0.9; // Slight drift
        }
      } else {
        // Grounded Physics (Robot & Car)
        const speed = playerMode === PlayerMode.ROBOT ? PLAYER_SPEED_ROBOT : PLAYER_SPEED_CAR;
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }

        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && playerMode === PlayerMode.ROBOT) {
          player.vel.y = JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      const effectiveHeight = playerMode === PlayerMode.ROBOT ? 48 : 24;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }

      if (player.pos.x < 0) player.pos.x = 0;

      // Shooting Logic
      const canShoot = playerMode === PlayerMode.ROBOT || playerMode === PlayerMode.JET;
      const fireRate = Math.max(5, (playerMode === PlayerMode.JET ? 20 : 15) - (upgrades.weaponTier * 3));

      if (keys['Space'] && canShoot && e.frame - player.lastShot > fireRate) {
        bullets.push({
          pos: { 
            x: player.pos.x + (player.facing === 1 ? (playerMode === PlayerMode.JET ? 48 : 32) : 0), 
            y: player.pos.y + (playerMode === PlayerMode.JET ? 12 : 15) 
          },
          vel: { x: player.facing * 12, y: 0 },
          width: 8,
          height: 4,
          owner: 'player',
          health: 1,
          maxHealth: 1,
          damage: 25
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) {
          bullets.splice(i, 1);
        }
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        const isTitan = enemy.type === 'titan';
        const attackRange = isTitan ? 600 : 400;
        const cooldown = isTitan ? 50 : (60 + Math.random() * 60);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (isTitan) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 40 },
                vel: { x: dir * 7, y: angle },
                width: 14,
                height: 14,
                owner: 'enemy',
                health: 1,
                maxHealth: 1,
                damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8,
              height: 4,
              owner: 'enemy',
              health: 1,
              maxHealth: 1,
              damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        // Collision detection
        const pWidth = playerMode === PlayerMode.ROBOT ? 32 : 48;
        const pHeight = effectiveHeight;

        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + pHeight > enemy.pos.y) {

          if (playerMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            if (isTitan) {
               enemy.health -= 100;
               if (enemy.health <= 0) enemy.isDead = true;
            } else {
               enemy.isDead = true;
               enemy.health = 0;
            }
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
                const dmg = isTitan ? 25 : 10;
                const newH = Math.max(0, h - dmg);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = playerMode === PlayerMode.ROBOT ? 32 : 48;
        const pHeight = effectiveHeight;
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + pHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const newH = Math.max(0, h - (b.damage || 5));
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, cameraX } = e;

      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY);
      ctx.lineTo(CANVAS_WIDTH, floorY);
      ctx.stroke();

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isTitan = enemy.type === 'titan';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (isTitan) {
          ctx.fillStyle = '#440022';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055';
          ctx.lineWidth = 2;
          ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(10, 20, 15, 10);
          ctx.fillRect(enemy.width-25, 20, 15, 10);
        } else {
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(5, 10, 5, 5);
          ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isTitan ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (playerMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4);
      } else if (playerMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 16, 8, 8);
        ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, -8, 16, 8);
      } else {
        // JET RENDER
        ctx.fillStyle = '#00f3ff';
        // Fuselage
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(48, 12);
        ctx.lineTo(32, 0);
        ctx.lineTo(0, 0);
        ctx.fill();
        // Wings
        ctx.fillStyle = '#0066ff';
        ctx.beginPath();
        ctx.moveTo(10, 0);
        ctx.lineTo(25, -10);
        ctx.lineTo(35, 0);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(10, 12);
        ctx.lineTo(25, 22);
        ctx.lineTo(35, 12);
        ctx.fill();
        // Exhaust
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300';
        ctx.fillRect(-8, 2, 8, 8);
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [playerMode, resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 'AERIAL INTERCEPTOR';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 'text-cyan-300';

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${(health / maxHealth) * 100}%` }}
              ></div>
            </div>
          </div>
          <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
            MODE: {modeName}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
              ))}
            </div>
            {kills === 4 && <div className="text-[10px] text-yellow-400 font-bold animate-pulse mt-1">TITAN DETECTED</div>}
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-xs text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[T] Cycle Transform (Robot-Car-Jet)</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

