import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10; // Increased speed for Car mode
const PLAYER_SPEED_JET = 7;
const JUMP_FORCE = -10;

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);

  // Use refs to communicate with the RAF loop
  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused
  });

  // Keep the ref in sync with the prop
  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;

    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setPlayerMode(PlayerMode.ROBOT);

    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      const isTitan = i === 4;
      const baseHealth = 50 + level * 10;
      enemies.push({
        id: i,
        pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
        vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
        width: isTitan ? 64 : 32,
        height: isTitan ? 96 : 48,
        health: isTitan ? baseHealth * 6 : baseHealth,
        maxHealth: isTitan ? baseHealth * 6 : baseHealth,
        isDead: false,
        type: isTitan ? 'titan' : 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      // Dedicated Transformation Keys
      if (e.code === 'KeyR') setPlayerMode(PlayerMode.ROBOT);
      if (e.code === 'KeyC') setPlayerMode(PlayerMode.CAR);
      if (e.code === 'KeyJ') setPlayerMode(PlayerMode.JET);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets } = e;
      e.frame++;

      // Physics based on mode
      if (playerMode === PlayerMode.JET) {
        // High altitude flight
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }

        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -PLAYER_SPEED_JET;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = PLAYER_SPEED_JET;
        } else {
          player.vel.y *= 0.9;
        }
      } else {
        // Grounded movement (Car is quicker)
        const speed = playerMode === PlayerMode.ROBOT ? PLAYER_SPEED_ROBOT : PLAYER_SPEED_CAR;
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }

        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && playerMode === PlayerMode.ROBOT) {
          player.vel.y = JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      const effectiveHeight = playerMode === PlayerMode.ROBOT ? 48 : 24;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }

      if (player.pos.x < 0) player.pos.x = 0;

      // Shooting Logic - All modes can shoot now
      const fireRate = Math.max(5, (playerMode === PlayerMode.JET ? 18 : 12) - (upgrades.weaponTier * 3));

      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15; // Robot center
        if (playerMode === PlayerMode.JET) shotYOffset = 8; // Shoot "from above"
        if (playerMode === PlayerMode.CAR) shotYOffset = 20; // Shoot "from below" (chassis mounted)

        bullets.push({
          pos: { 
            x: player.pos.x + (player.facing === 1 ? (playerMode === PlayerMode.ROBOT ? 32 : 48) : 0), 
            y: player.pos.y + shotYOffset 
          },
          vel: { x: player.facing * 12, y: 0 },
          width: 8,
          height: 4,
          owner: 'player',
          health: 1,
          maxHealth: 1,
          damage: 25
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) {
          bullets.splice(i, 1);
        }
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        const isTitan = enemy.type === 'titan';
        const attackRange = isTitan ? 600 : 400;
        const cooldown = isTitan ? 50 : (60 + Math.random() * 60);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (isTitan) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 40 },
                vel: { x: dir * 7, y: angle },
                width: 14,
                height: 14,
                owner: 'enemy',
                health: 1,
                maxHealth: 1,
                damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8,
              height: 4,
              owner: 'enemy',
              health: 1,
              maxHealth: 1,
              damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (playerMode === PlayerMode.ROBOT) ? 32 : 48;
        const pHeight = effectiveHeight;

        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + pHeight > enemy.pos.y) {

          if (playerMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            if (isTitan) {
               enemy.health -= 100;
               if (enemy.health <= 0) enemy.isDead = true;
            } else {
               enemy.isDead = true;
               enemy.health = 0;
            }
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
                const dmg = isTitan ? 25 : 10;
                const newH = Math.max(0, h - dmg);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (playerMode === PlayerMode.ROBOT) ? 32 : 48;
        const pHeight = effectiveHeight;
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + pHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const newH = Math.max(0, h - (b.damage || 5));
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, cameraX } = e;

      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY);
      ctx.lineTo(CANVAS_WIDTH, floorY);
      ctx.stroke();

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isTitan = enemy.type === 'titan';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (isTitan) {
          ctx.fillStyle = '#440022';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055';
          ctx.lineWidth = 2;
          ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(10, 20, 15, 10);
          ctx.fillRect(enemy.width-25, 20, 15, 10);
        } else {
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(5, 10, 5, 5);
          ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isTitan ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (playerMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4);
      } else if (playerMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 16, 8, 8);
        ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, -8, 16, 8);
      } else {
        ctx.fillStyle = '#00f3ff';
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(48, 12);
        ctx.lineTo(32, 0);
        ctx.lineTo(0, 0);
        ctx.fill();
        ctx.fillStyle = '#0066ff';
        ctx.beginPath();
        ctx.moveTo(10, 0);
        ctx.lineTo(25, -10);
        ctx.lineTo(35, 0);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(10, 12);
        ctx.lineTo(25, 22);
        ctx.lineTo(35, 12);
        ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300';
        ctx.fillRect(-8, 2, 8, 8);
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [playerMode, resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 'AERIAL INTERCEPTOR';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 'text-cyan-300';

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${(health / maxHealth) * 100}%` }}
              ></div>
            </div>
          </div>
          <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
            MODE: {modeName}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
              ))}
            </div>
            {kills === 4 && <div className="text-[10px] text-yellow-400 font-bold animate-pulse mt-1">TITAN DETECTED</div>}
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car [J] Jet</div>
        <div>[P] Pause Mission</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP'
}

export enum PlayerMode {
  ROBOT = 'ROBOT',
  CAR = 'CAR',
  JET = 'JET',
  TITAN = 'TITAN'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 7;
const PLAYER_SPEED_TITAN = 3; // Titan is heavy and slower
const JUMP_FORCE = -10;
const TITAN_JUMP_FORCE = -12;

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);

  // Use refs to communicate with the RAF loop
  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused
  });

  // Keep the ref in sync with the prop
  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;

    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies if level 2 or higher
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 300 },
          offset: { 
            x: -40 - Math.random() * 40, 
            y: -20 - Math.random() * 40 
          }
        });
      }
    }

    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      const isTitan = i === 4;
      const baseHealth = 50 + level * 10;
      enemies.push({
        id: i,
        pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
        vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
        width: isTitan ? 64 : 32,
        height: isTitan ? 96 : 48,
        health: isTitan ? baseHealth * 6 : baseHealth,
        maxHealth: isTitan ? baseHealth * 6 : baseHealth,
        isDead: false,
        type: isTitan ? 'titan' : 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      // Dedicated Transformation Keys
      if (e.code === 'KeyR') setPlayerMode(PlayerMode.ROBOT);
      if (e.code === 'KeyC') setPlayerMode(PlayerMode.CAR);
      if (e.code === 'KeyJ') setPlayerMode(PlayerMode.JET);
      if (e.code === 'KeyK' && level >= 2) setPlayerMode(PlayerMode.TITAN);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies } = e;
      e.frame++;

      // Physics based on mode
      if (playerMode === PlayerMode.JET) {
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }

        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -PLAYER_SPEED_JET;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = PLAYER_SPEED_JET;
        } else {
          player.vel.y *= 0.9;
        }
      } else {
        let speed = PLAYER_SPEED_ROBOT;
        if (playerMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
        if (playerMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }

        const canJump = playerMode === PlayerMode.ROBOT || playerMode === PlayerMode.TITAN;
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
          player.vel.y = playerMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (playerMode === PlayerMode.CAR) effectiveHeight = 24;
      if (playerMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }

      if (player.pos.x < 0) player.pos.x = 0;

      // Update Allies
      if (playerMode !== PlayerMode.TITAN) {
        allies.forEach((ally, i) => {
          const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 20);
          const targetY = player.pos.y + ally.offset.y;
          ally.pos.x += (targetX - ally.pos.x) * 0.1;
          ally.pos.y += (targetY - ally.pos.y) * 0.1;
        });
      } else {
        // In Titan mode, allies "disappear" into the frame
        allies.forEach(ally => {
          ally.pos.x = player.pos.x + 16;
          ally.pos.y = player.pos.y + 32;
        });
      }

      // Shooting Logic
      const fireRate = Math.max(5, (playerMode === PlayerMode.JET ? 18 : (playerMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));

      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (playerMode === PlayerMode.JET) shotYOffset = 8;
        if (playerMode === PlayerMode.CAR) shotYOffset = 20;
        if (playerMode === PlayerMode.TITAN) shotYOffset = 30;

        if (playerMode === PlayerMode.TITAN) {
          // Titan fires triple heavy shots
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { 
                x: player.pos.x + (player.facing === 1 ? 64 : 0), 
                y: player.pos.y + shotYOffset + (i * 20)
              },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16,
              height: 8,
              owner: 'player',
              health: 1,
              maxHealth: 1,
              damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { 
              x: player.pos.x + (player.facing === 1 ? (playerMode === PlayerMode.ROBOT ? 32 : 48) : 0), 
              y: player.pos.y + shotYOffset 
            },
            vel: { x: player.facing * 12, y: 0 },
            width: 8,
            height: 4,
            owner: 'player',
            health: 1,
            maxHealth: 1,
            damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) {
          bullets.splice(i, 1);
        }
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        const isTitanEnemy = enemy.type === 'titan';
        const attackRange = isTitanEnemy ? 600 : 400;
        const cooldown = isTitanEnemy ? 50 : (60 + Math.random() * 60);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (isTitanEnemy) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 40 },
                vel: { x: dir * 7, y: angle },
                width: 14,
                height: 14,
                owner: 'enemy',
                health: 1,
                maxHealth: 1,
                damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8,
              height: 4,
              owner: 'enemy',
              health: 1,
              maxHealth: 1,
              damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (playerMode === PlayerMode.ROBOT) ? 32 : (playerMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;

        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + pHeight > enemy.pos.y) {

          if (playerMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            if (isTitanEnemy) {
               enemy.health -= 100;
               if (enemy.health <= 0) enemy.isDead = true;
            } else {
               enemy.isDead = true;
               enemy.health = 0;
            }
          } else if (playerMode === PlayerMode.TITAN) {
              // Titan deals contact damage but also takes less relative damage
              enemy.health -= 1;
              if (enemy.health <= 0) enemy.isDead = true;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
                const dmg = isTitanEnemy ? 25 : 10;
                const newH = Math.max(0, h - dmg);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (playerMode === PlayerMode.ROBOT) ? 32 : (playerMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + pHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmgTaken = b.damage || 5;
              // Titan takes 50% reduced damage
              const finalDmg = playerMode === PlayerMode.TITAN ? dmgTaken * 0.5 : dmgTaken;
              const newH = Math.max(0, h - finalDmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;

      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY);
      ctx.lineTo(CANVAS_WIDTH, floorY);
      ctx.stroke();

      // Draw Allies (Drones)
      if (playerMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.fillStyle = '#00f3ff';
          ctx.beginPath();
          ctx.arc(ally.pos.x - cameraX, ally.pos.y, 6, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 10;
          ctx.shadowColor = '#00f3ff';
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 1;
          ctx.stroke();
          ctx.shadowBlur = 0;
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isTitanEnemy = enemy.type === 'titan';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (isTitanEnemy) {
          ctx.fillStyle = '#440022';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055';
          ctx.lineWidth = 2;
          ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(10, 20, 15, 10);
          ctx.fillRect(enemy.width-25, 20, 15, 10);
        } else {
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(5, 10, 5, 5);
          ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isTitanEnemy ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (playerMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4);
      } else if (playerMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 16, 8, 8);
        ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, -8, 16, 8);
      } else if (playerMode === PlayerMode.JET) {
        ctx.fillStyle = '#00f3ff';
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(48, 12);
        ctx.lineTo(32, 0);
        ctx.lineTo(0, 0);
        ctx.fill();
        ctx.fillStyle = '#0066ff';
        ctx.beginPath();
        ctx.moveTo(10, 0);
        ctx.lineTo(25, -10);
        ctx.lineTo(35, 0);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(10, 12);
        ctx.lineTo(25, 22);
        ctx.lineTo(35, 12);
        ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300';
        ctx.fillRect(-8, 2, 8, 8);
      } else if (playerMode === PlayerMode.TITAN) {
        // Render Powerful Titan
        ctx.fillStyle = '#003366';
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 4;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff';
        ctx.fillRect(12, 12, 40, 20); // Massive Vizor
        ctx.fillStyle = '#ffcc00';
        ctx.fillRect(10, 45, 12, 12); // Chest Reactor
        ctx.fillRect(42, 45, 12, 12);
        ctx.shadowBlur = 20;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [playerMode, resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${(health / maxHealth) * 100}%` }}
              ></div>
            </div>
          </div>
          <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
            MODE: {modeName}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
              ))}
            </div>
            {kills === 4 && <div className="text-[10px] text-yellow-400 font-bold animate-pulse mt-1">TITAN DETECTED</div>}
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car [J] Jet</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE (4/4 Drones)</div>}
        <div>[P] Pause Mission</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 7;
const PLAYER_SPEED_TITAN = 3; // Titan is heavy and slower
const JUMP_FORCE = -10;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds at 60fps

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [titanFramesLeft, setTitanFramesLeft] = useState(0);

  // Use refs to communicate with the RAF loop
  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      titanTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT
  });

  // Keep the refs in sync with props/state that engine needs
  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;

    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.titanTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setTitanFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies if level 2 or higher
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 300 },
          offset: { 
            x: -40 - Math.random() * 40, 
            y: -20 - Math.random() * 40 
          }
        });
      }
    }

    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      const isTitan = i === 4;
      const baseHealth = 50 + level * 10;
      enemies.push({
        id: i,
        pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
        vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
        width: isTitan ? 64 : 32,
        height: isTitan ? 96 : 48,
        health: isTitan ? baseHealth * 6 : baseHealth,
        maxHealth: isTitan ? baseHealth * 6 : baseHealth,
        isDead: false,
        type: isTitan ? 'titan' : 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      // Dedicated Transformation Keys
      if (e.code === 'KeyR') setPlayerMode(PlayerMode.ROBOT);
      if (e.code === 'KeyC') setPlayerMode(PlayerMode.CAR);
      if (e.code === 'KeyJ') setPlayerMode(PlayerMode.JET);
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.titanTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies } = e;
      const currentMode = e.mode;
      e.frame++;

      // Titan Timer Logic
      if (currentMode === PlayerMode.TITAN) {
        player.titanTimer--;
        // Update UI every 10 frames to save on React cycles
        if (e.frame % 10 === 0) {
          setTitanFramesLeft(player.titanTimer);
        }
        if (player.titanTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setTitanFramesLeft(0);
        }
      }

      // Physics based on mode
      if (currentMode === PlayerMode.JET) {
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }

        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -PLAYER_SPEED_JET;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = PLAYER_SPEED_JET;
        } else {
          player.vel.y *= 0.9;
        }
      } else {
        let speed = PLAYER_SPEED_ROBOT;
        if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
        if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }

        const canJump = currentMode === PlayerMode.ROBOT || currentMode === PlayerMode.TITAN;
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
          player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }

      if (player.pos.x < 0) player.pos.x = 0;

      // Update Allies
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach((ally, i) => {
          const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 20);
          const targetY = player.pos.y + ally.offset.y;
          ally.pos.x += (targetX - ally.pos.x) * 0.1;
          ally.pos.y += (targetY - ally.pos.y) * 0.1;
        });
      } else {
        allies.forEach(ally => {
          ally.pos.x = player.pos.x + 16;
          ally.pos.y = player.pos.y + 32;
        });
      }

      // Shooting Logic
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 18 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));

      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 8;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { 
                x: player.pos.x + (player.facing === 1 ? 64 : 0), 
                y: player.pos.y + shotYOffset + (i * 20)
              },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16,
              height: 8,
              owner: 'player',
              health: 1,
              maxHealth: 1,
              damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { 
              x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), 
              y: player.pos.y + shotYOffset 
            },
            vel: { x: player.facing * 12, y: 0 },
            width: 8,
            height: 4,
            owner: 'player',
            health: 1,
            maxHealth: 1,
            damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) {
          bullets.splice(i, 1);
        }
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        const isTitanEnemy = enemy.type === 'titan';
        const attackRange = isTitanEnemy ? 600 : 400;
        const cooldown = isTitanEnemy ? 50 : (60 + Math.random() * 60);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (isTitanEnemy) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 40 },
                vel: { x: dir * 7, y: angle },
                width: 14,
                height: 14,
                owner: 'enemy',
                health: 1,
                maxHealth: 1,
                damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8,
              height: 4,
              owner: 'enemy',
              health: 1,
              maxHealth: 1,
              damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;

        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + pHeight > enemy.pos.y) {

          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            if (isTitanEnemy) {
               enemy.health -= 100;
               if (enemy.health <= 0) enemy.isDead = true;
            } else {
               enemy.isDead = true;
               enemy.health = 0;
            }
          } else if (currentMode === PlayerMode.TITAN) {
              enemy.health -= 1;
              if (enemy.health <= 0) enemy.isDead = true;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
                const dmg = isTitanEnemy ? 25 : 10;
                const newH = Math.max(0, h - dmg);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + pHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmgTaken = b.damage || 5;
              const finalDmg = currentMode === PlayerMode.TITAN ? dmgTaken * 0.5 : dmgTaken;
              const newH = Math.max(0, h - finalDmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY);
      ctx.lineTo(CANVAS_WIDTH, floorY);
      ctx.stroke();

      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.fillStyle = '#00f3ff';
          ctx.beginPath();
          ctx.arc(ally.pos.x - cameraX, ally.pos.y, 6, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 10;
          ctx.shadowColor = '#00f3ff';
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 1;
          ctx.stroke();
          ctx.shadowBlur = 0;
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isTitanEnemy = enemy.type === 'titan';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (isTitanEnemy) {
          ctx.fillStyle = '#440022';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055';
          ctx.lineWidth = 2;
          ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(10, 20, 15, 10);
          ctx.fillRect(enemy.width-25, 20, 15, 10);
        } else {
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(5, 10, 5, 5);
          ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isTitanEnemy ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 16, 8, 8);
        ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00f3ff';
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(48, 12);
        ctx.lineTo(32, 0);
        ctx.lineTo(0, 0);
        ctx.fill();
        ctx.fillStyle = '#0066ff';
        ctx.beginPath();
        ctx.moveTo(10, 0);
        ctx.lineTo(25, -10);
        ctx.lineTo(35, 0);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(10, 12);
        ctx.lineTo(25, 22);
        ctx.lineTo(35, 12);
        ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300';
        ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        ctx.fillStyle = '#003366';
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 4;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff';
        ctx.fillRect(12, 12, 40, 20); 
        ctx.fillStyle = '#ffcc00';
        ctx.fillRect(10, 45, 12, 12); 
        ctx.fillRect(42, 45, 12, 12);
        ctx.shadowBlur = 20;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${(health / maxHealth) * 100}%` }}
              ></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
              MODE: {modeName}
            </div>
            {playerMode === PlayerMode.TITAN && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Titan Stabilization</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" 
                      style={{ width: `${(titanFramesLeft / TITAN_DURATION_FRAMES) * 100}%` }}
                    ></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(titanFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
              ))}
            </div>
            {kills === 4 && <div className="text-[10px] text-yellow-400 font-bold animate-pulse mt-1">TITAN DETECTED</div>}
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car [J] Jet</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE (Limited Time)</div>}
        <div>[P] Pause Mission</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 7;
const PLAYER_SPEED_TITAN = 3; 
const JUMP_FORCE = -10;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);

  // Use refs to communicate with the RAF loop
  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT
  });

  // Keep the refs in sync with props/state that engine needs
  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;

    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies if level 2 or higher
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 300 },
          offset: { 
            x: -60 - i * 40, 
            y: -10 - Math.random() * 20 
          }
        });
      }
    }

    const enemies: Enemy[] = [];
    for (let i = 0; i < 5; i++) {
      const isTitan = i === 4;
      const baseHealth = 50 + level * 10;
      enemies.push({
        id: i,
        pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
        vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
        width: isTitan ? 64 : 32,
        height: isTitan ? 96 : 48,
        health: isTitan ? baseHealth * 6 : baseHealth,
        maxHealth: isTitan ? baseHealth * 6 : baseHealth,
        isDead: false,
        type: isTitan ? 'titan' : 'bot',
        lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      // Dedicated Transformation Keys
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies } = e;
      const currentMode = e.mode;
      e.frame++;

      // Mode Timer Logic
      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) {
          setModeFramesLeft(player.modeTimer);
        }
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      // Physics based on mode
      if (currentMode === PlayerMode.JET) {
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }

        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -PLAYER_SPEED_JET;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = PLAYER_SPEED_JET;
        } else {
          player.vel.y *= 0.9;
        }
      } else {
        let speed = PLAYER_SPEED_ROBOT;
        if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
        if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }

        const canJump = currentMode === PlayerMode.ROBOT || currentMode === PlayerMode.TITAN;
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
          player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }

      if (player.pos.x < 0) player.pos.x = 0;

      // Update Allies (Now same size as Robot mode)
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach((ally, i) => {
          const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
          const targetY = player.pos.y + ally.offset.y;
          ally.pos.x += (targetX - ally.pos.x) * 0.08;
          ally.pos.y += (targetY - ally.pos.y) * 0.08;
        });
      } else {
        allies.forEach(ally => {
          ally.pos.x = player.pos.x + 16;
          ally.pos.y = player.pos.y + 32;
        });
      }

      // Shooting Logic
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 18 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));

      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 8;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { 
                x: player.pos.x + (player.facing === 1 ? 64 : 0), 
                y: player.pos.y + shotYOffset + (i * 20)
              },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16,
              height: 8,
              owner: 'player',
              health: 1,
              maxHealth: 1,
              damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { 
              x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), 
              y: player.pos.y + shotYOffset 
            },
            vel: { x: player.facing * 12, y: 0 },
            width: 8,
            height: 4,
            owner: 'player',
            health: 1,
            maxHealth: 1,
            damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) {
          bullets.splice(i, 1);
        }
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) {
          currentKills++;
          return;
        }

        enemy.pos.x += enemy.vel.x;
        if (Math.random() < 0.01) enemy.vel.x *= -1;

        const isTitanEnemy = enemy.type === 'titan';
        const attackRange = isTitanEnemy ? 600 : 400;
        const cooldown = isTitanEnemy ? 50 : (60 + Math.random() * 60);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (isTitanEnemy) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 40 },
                vel: { x: dir * 7, y: angle },
                width: 14,
                height: 14,
                owner: 'enemy',
                health: 1,
                maxHealth: 1,
                damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8,
              height: 4,
              owner: 'enemy',
              health: 1,
              maxHealth: 1,
              damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;

        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + pHeight > enemy.pos.y) {

          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
            if (isTitanEnemy) {
               enemy.health -= 100;
               if (enemy.health <= 0) enemy.isDead = true;
            } else {
               enemy.isDead = true;
               enemy.health = 0;
            }
          } else if (currentMode === PlayerMode.TITAN) {
              enemy.health -= 1;
              if (enemy.health <= 0) enemy.isDead = true;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
                const dmg = isTitanEnemy ? 25 : 10;
                const newH = Math.max(0, h - dmg);
                if (newH === 0) onDie();
                return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        const pHeight = effectiveHeight;
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + pHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmgTaken = b.damage || 5;
              const finalDmg = currentMode === PlayerMode.TITAN ? dmgTaken * 0.5 : dmgTaken;
              const newH = Math.max(0, h - finalDmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;

      setKills(currentKills);
      if (currentKills === 5) {
        onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.strokeStyle = '#112233';
      ctx.lineWidth = 1;
      for (let x = -cameraX % 100; x < CANVAS_WIDTH; x += 100) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
        ctx.stroke();
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#001122';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY);
      ctx.lineTo(CANVAS_WIDTH, floorY);
      ctx.stroke();

      // Draw Allies (Same size as Player Robot)
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = '#006699';
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = '#00ccff';
          ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(8, 8, 16, 8); // Vizor
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isTitanEnemy = enemy.type === 'titan';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (isTitanEnemy) {
          ctx.fillStyle = '#440022';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055';
          ctx.lineWidth = 2;
          ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(10, 20, 15, 10);
          ctx.fillRect(enemy.width-25, 20, 15, 10);
        } else {
          ctx.fillStyle = '#ff0055';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(5, 10, 5, 5);
          ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000';
        ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isTitanEnemy ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white';
        ctx.fillRect(10, 8, 12, 4);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff';
        ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000';
        ctx.fillRect(5, 16, 8, 8);
        ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00f3ff';
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(48, 12);
        ctx.lineTo(32, 0);
        ctx.lineTo(0, 0);
        ctx.fill();
        ctx.fillStyle = '#0066ff';
        ctx.beginPath();
        ctx.moveTo(10, 0);
        ctx.lineTo(25, -10);
        ctx.lineTo(35, 0);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(10, 12);
        ctx.lineTo(25, 22);
        ctx.lineTo(35, 12);
        ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300';
        ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        ctx.fillStyle = '#003366';
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 4;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff';
        ctx.fillRect(12, 12, 40, 20); 
        ctx.fillStyle = '#ffcc00';
        ctx.fillRect(10, 45, 12, 12); 
        ctx.fillRect(42, 45, 12, 12);
        ctx.shadowBlur = 20;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10;
        ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div 
                className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" 
                style={{ width: `${(health / maxHealth) * 100}%` }}
              ></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>
              MODE: {modeName}
            </div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Stability Sync</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" 
                      style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}
                    ></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(modeFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
            <div className="flex gap-1 justify-end">
              {[...Array(5)].map((_, i) => (
                <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
              ))}
            </div>
            {kills === 4 && <div className="text-[10px] text-yellow-400 font-bold animate-pulse mt-1">TITAN DETECTED</div>}
          </div>
          <div className="text-white font-bold text-xl font-mono">
            SECTOR {level} / 20
          </div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car (30s) [J] Jet (30s)</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE (60s)</div>}
        <div>[P] Pause Mission</div>
      </div>

      <canvas 
        ref={canvasRef} 
        width={CANVAS_WIDTH} 
        height={CANVAS_HEIGHT}
        className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"
      />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 7;
const PLAYER_SPEED_TITAN = 3; 
const JUMP_FORCE = -10;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; // Goal distance for Level 5

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -60 - i * 45, y: 0 }
        });
      }
    }

    const enemies: Enemy[] = [];
    if (level === 5) {
      // Level 5: One big tank that chases and shoots
      enemies.push({
        id: 0,
        pos: { x: -200, y: 350 + 48 - 80 },
        vel: { x: 4.5, y: 0 }, // Slightly faster than robot, but slower than car
        width: 120,
        height: 80,
        health: 500,
        maxHealth: 500,
        isDead: false,
        type: 'tank',
        lastShot: 0
      });
      // Add some small interference bots
      for (let i = 1; i < 5; i++) {
        enemies.push({
          id: i,
          pos: { x: 800 + i * 800, y: 350 + 48 - 48 },
          vel: { x: 0, y: 0 },
          width: 32,
          height: 48,
          health: 50,
          maxHealth: 50,
          isDead: false,
          type: 'bot',
          lastShot: 0
        });
      }
    } else if (level === 20) {
      // Level 20: Medium-sized gray boss with 200 HP
      enemies.push({
        id: 0,
        pos: { x: 800, y: 350 + 48 - 64 },
        vel: { x: 0, y: 0 },
        width: 48,
        height: 64,
        health: 200,
        maxHealth: 200,
        isDead: false,
        type: 'gray_boss',
        lastShot: 0
      });
      // Plus 4 defenders
      for (let i = 1; i < 5; i++) {
        enemies.push({
          id: i,
          pos: { x: 1000 + i * 200, y: 350 + 48 - 48 },
          vel: { x: 0, y: 0 },
          width: 32,
          height: 48,
          health: 100,
          maxHealth: 100,
          isDead: false,
          type: 'bot',
          lastShot: 0
        });
      }
    } else {
      // Standard Levels
      for (let i = 0; i < 5; i++) {
        const isTitan = i === 4 && level > 5;
        const baseHealth = 50 + level * 10;
        enemies.push({
          id: i,
          pos: { x: 800 + i * 500 + Math.random() * 100, y: isTitan ? 350 + 48 - 96 : 350 + 48 - 48 },
          vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
          width: isTitan ? 64 : 32,
          height: isTitan ? 96 : 48,
          health: isTitan ? baseHealth * 6 : baseHealth,
          maxHealth: isTitan ? baseHealth * 6 : baseHealth,
          isDead: false,
          type: isTitan ? 'titan' : 'bot',
          lastShot: 0
        });
      }
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      if (currentMode === PlayerMode.JET) {
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = PLAYER_SPEED_JET;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -PLAYER_SPEED_JET;
          player.facing = -1;
        } else {
          player.vel.x *= 0.95;
        }
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -PLAYER_SPEED_JET;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = PLAYER_SPEED_JET;
        else player.vel.y *= 0.9;
      } else {
        let speed = PLAYER_SPEED_ROBOT;
        if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
        if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;
        if (keys['ArrowRight'] || keys['KeyD']) {
          player.vel.x = speed;
          player.facing = 1;
        } else if (keys['ArrowLeft'] || keys['KeyA']) {
          player.vel.x = -speed;
          player.facing = -1;
        } else {
          player.vel.x *= 0.8;
        }
        const canJump = currentMode === PlayerMode.ROBOT || currentMode === PlayerMode.TITAN;
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
          player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;
      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Allies stay on the ground
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach((ally, i) => {
          const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
          ally.pos.x += (targetX - ally.pos.x) * 0.08;
          ally.pos.y = floorY - 48; // Stay on floor
        });
      } else {
        allies.forEach(ally => {
          ally.pos.x = player.pos.x + 16;
          ally.pos.y = player.pos.y + 32;
        });
      }

      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 18 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 8;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;
        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 12, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) bullets.splice(i, 1);
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) { currentKills++; return; }

        if (enemy.type === 'tank') {
          // Tank chases player from the left
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 50) enemy.pos.x = player.pos.x - 50;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.01) enemy.vel.x *= -1;
        }

        const isBoss = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBoss ? 800 : 400;
        const cooldown = enemy.type === 'tank' ? 40 : (isBoss ? 50 : (60 + Math.random() * 60));

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 8, y: 0 },
              width: 20, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 20
            });
          } else if (enemy.type === 'titan' || enemy.type === 'gray_boss') {
            for (let angle = -2; angle <= 2; angle += 2) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 30 },
                vel: { x: dir * 7, y: angle },
                width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
             enemy.health -= isBoss ? 50 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBoss ? 30 : 10;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.5 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        if (currentKills === 5) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      // Background - Burning Buildings
      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Distant building silhouettes with fire
      const buildColors = ['#0a0a15', '#0d0d1a', '#101020'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.2;
        const offsetX = -(cameraX * speed) % 200;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 200; x += 150) {
          const h = 150 + (i * 50) + Math.sin(x) * 30;
          ctx.fillRect(x, CANVAS_HEIGHT - h - 52, 120, h);

          // Fire on buildings
          if ((x + e.frame) % 100 < 20) {
            ctx.fillStyle = e.frame % 10 < 5 ? '#ff4400' : '#ff8800';
            ctx.beginPath();
            ctx.arc(x + 20 + Math.random() * 80, CANVAS_HEIGHT - h - 52 + Math.random() * 20, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#111111';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      // Allies
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = '#006699';
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = '#00ccff'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#333333';
          ctx.fillRect(0, 20, 120, 60);
          ctx.fillRect(20, 0, 80, 40);
          ctx.fillStyle = '#000000';
          ctx.fillRect(100, 15, 40, 10);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(30, 10, 10, 10);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#777777';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#999999'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 5);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#440022'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#330000'; ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = (enemy.type === 'titan' || enemy.type === 'tank') ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);
      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff'; ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white'; ctx.fillRect(10, 8, 12, 4);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00f3ff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(48, 12); ctx.lineTo(32, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0066ff'; ctx.beginPath();
        ctx.moveTo(10, 0); ctx.lineTo(25, -10); ctx.lineTo(35, 0); ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300'; ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        ctx.fillStyle = '#003366'; ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff'; ctx.fillRect(12, 12, 40, 20); 
        ctx.fillStyle = '#ffcc00'; ctx.fillRect(10, 45, 12, 12); ctx.fillRect(42, 45, 12, 12);
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>MODE: {modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Stability Sync</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(modeFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            {level === 5 ? (
              <>
                <div className="text-xs text-yellow-500 font-bold uppercase mb-1">ESCAPE DISTANCE</div>
                <div className="text-xl font-black text-white">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
                <div className="flex gap-1 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-bold text-xl font-mono">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move / Fly</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car [J] Jet</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE</div>}
        <div>[P] Pause</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"/>
    </div>
  );
};

export default GameView;

import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "This is an escape mission! The player must run away from a giant shooting tank across a burning city.";
  if (level === 20) specialPrompt = "This is the final showdown! The player must destroy a medium-sized gray boss robot with 200 HP.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short cyberpunk mission briefing for Level ${level} of a robot police officer game. 
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the threat in the burning city.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini failed, using fallback briefing", error);
    return {
      level,
      title: level === 20 ? "The Final Enforcer" : (level === 5 ? "Death Chase" : `Sector ${level} Purge`),
      description: level === 5 
        ? "A massive siege tank is pursuing you. Reach the extraction point before you are pulverized." 
        : (level === 20 ? "The Rogue Alpha has been cornered. Neutralize the gray enforcer to end the war." : "Hostile units detected in the burning sector. Cleanse the area."),
      threatLevel: level >= 15 ? "Extreme" : "High",
      enemyType: level === 5 ? "Siege Tank" : (level === 20 ? "Alpha Enforcer" : "Rogue Battalion")
    };
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 8; 
const PLAYER_SPEED_TITAN = 3; 
const JUMP_FORCE = -10;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; // Goal distance for Level 5 extraction

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -60 - i * 45, y: 0 }
        });
      }
    }

    const enemies: Enemy[] = [];
    if (level === 5) {
      // Level 5: Escape from tank
      enemies.push({
        id: 0,
        pos: { x: -400, y: 350 + 48 - 80 },
        vel: { x: 4.8, y: 0 }, 
        width: 140,
        height: 80,
        health: 1000,
        maxHealth: 1000,
        isDead: false,
        type: 'tank',
        lastShot: 0
      });
      for (let i = 1; i < 5; i++) {
        enemies.push({
          id: i,
          pos: { x: 800 + i * 800, y: 350 + 48 - 48 },
          vel: { x: 0, y: 0 },
          width: 32,
          height: 48,
          health: 50,
          maxHealth: 50,
          isDead: false,
          type: 'bot',
          lastShot: 0
        });
      }
    } else if (level === 20) {
      // Level 20: Gray boss with 200 hp
      enemies.push({
        id: 0,
        pos: { x: 1000, y: 350 + 48 - 64 },
        vel: { x: 0, y: 0 },
        width: 48,
        height: 64,
        health: 200,
        maxHealth: 200,
        isDead: false,
        type: 'gray_boss',
        lastShot: 0
      });
      for (let i = 1; i < 5; i++) {
        enemies.push({
          id: i,
          pos: { x: 1200 + i * 300, y: 350 + 48 - 48 },
          vel: { x: 0, y: 0 },
          width: 32,
          height: 48,
          health: 100,
          maxHealth: 100,
          isDead: false,
          type: 'bot',
          lastShot: 0
        });
      }
    } else {
      for (let i = 0; i < 5; i++) {
        const isTitan = i === 4 && level > 5;
        const baseHealth = 50 + level * 10;
        enemies.push({
          id: i,
          pos: { x: 800 + i * 500 + Math.random() * 100, y: 350 + 48 - (isTitan ? 96 : 48) },
          vel: { x: (Math.random() - 0.5) * (isTitan ? 1 : 2.5), y: 0 },
          width: isTitan ? 64 : 32,
          height: isTitan ? 96 : 48,
          health: isTitan ? baseHealth * 6 : baseHealth,
          maxHealth: isTitan ? baseHealth * 6 : baseHealth,
          isDead: false,
          type: isTitan ? 'titan' : 'bot',
          lastShot: 0
        });
      }
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      // Physics - Grounded per request
      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      const canJump = currentMode === PlayerMode.ROBOT || currentMode === PlayerMode.TITAN;
      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
        player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
        player.grounded = false;
      }
      player.vel.y += GRAVITY;

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      } else if (player.pos.y < 20) {
        player.pos.y = 20;
        player.vel.y = 0;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Allies stay on ground
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach((ally) => {
          const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
          ally.pos.x += (targetX - ally.pos.x) * 0.08;
          ally.pos.y = floorY - 48; 
        });
      } else {
        allies.forEach(ally => {
          ally.pos.x = player.pos.x + 16;
          ally.pos.y = player.pos.y + 32;
        });
      }

      // Shooting
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 18 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 12, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1200 || b.pos.y > 600 || b.pos.y < -200) bullets.splice(i, 1);
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) { currentKills++; return; }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 50) enemy.pos.x = player.pos.x - 50;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.01) enemy.vel.x *= -1;
        }

        const isBoss = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBoss ? 800 : 400;
        const cooldown = enemy.type === 'tank' ? 40 : (isBoss ? 50 : (60 + Math.random() * 60));

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 8, y: 0 },
              width: 20, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 20
            });
          } else if (isBoss) {
            for (let angle = -2; angle <= 2; angle += 2) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 30 },
                vel: { x: dir * 7, y: angle },
                width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 },
              width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {

          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 5) {
             // Ramming rule: Titan, Tank, GrayBoss only take little damage (5 HP) in car mode
             enemy.health -= isBoss ? 5 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.4; // Recoil
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBoss ? 30 : 10;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.5 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        if (currentKills === 5) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      // Background - Burning Buildings for all levels
      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a25', '#101030'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.15;
        const offsetX = -(cameraX * speed) % 350;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 350; x += 220) {
          const h = 240 + (i * 50) + Math.sin(x) * 40;
          const buildX = x;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(buildX, buildY, 150, h);

          // Fire effects on buildings
          if ((buildX + e.frame * 1.5) % 200 < 60) {
            ctx.fillStyle = e.frame % 12 < 6 ? '#ff3300' : '#ff9900';
            ctx.beginPath();
            const fX = buildX + 20 + Math.random() * 100;
            const fY = buildY + Math.random() * 50;
            ctx.arc(fX, fY, 12 + Math.random()*8, 0, Math.PI * 2);
            ctx.fill();

            // Rising smoke
            ctx.fillStyle = 'rgba(50, 50, 60, 0.3)';
            ctx.beginPath();
            ctx.arc(fX + Math.sin(e.frame/20)*15, fY - 30 - (e.frame % 60), 15, 0, Math.PI*2);
            ctx.fill();

            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#111111';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      // Allies
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = '#004466';
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = '#00ccff'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = '#00ffff'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBoss = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222222';
          ctx.fillRect(0, 20, 140, 60);
          ctx.fillRect(30, 0, 80, 40);
          ctx.fillStyle = '#000000';
          ctx.fillRect(110, 15, 55, 12);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(45, 12, 18, 18);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#555555';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#888888'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(12, 12, 24, 8);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#300015'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 15, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = (isBoss) ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);
      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff'; ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white'; ctx.fillRect(10, 8, 12, 4);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00f3ff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(48, 12); ctx.lineTo(32, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0066ff'; ctx.beginPath();
        ctx.moveTo(10, 0); ctx.lineTo(25, -10); ctx.lineTo(35, 0); ctx.fill();
        ctx.fillStyle = e.frame % 4 < 2 ? '#ffaa00' : '#ff3300'; ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        ctx.fillStyle = '#003366'; ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff'; ctx.fillRect(12, 12, 40, 20); 
        ctx.fillStyle = '#ffcc00'; ctx.fillRect(10, 45, 12, 12); ctx.fillRect(42, 45, 12, 12);
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'GROUND-STRIKE JET' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>MODE: {modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Stability Sync</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(modeFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            {level === 5 ? (
              <>
                <div className="text-xs text-yellow-500 font-bold uppercase mb-1">ESCAPE DISTANCE</div>
                <div className="text-xl font-black text-white">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
                <div className="flex gap-1 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-bold text-xl font-mono">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD/ARROWS] Move</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car (30s) [J] Ground-Jet (30s)</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE (60s)</div>}
        <div>[P] Pause</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"/>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 9; 
const PLAYER_SPEED_TITAN = 3; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number } }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies - same size as robot
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -70 - i * 50, y: 0 }
        });
      }
    }

    const enemies: Enemy[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      // Tank + 3 bots + 1 Titan (Last enemy)
      enemies.push({
        id: 0, pos: { x: -500, y: floorY - 80 }, vel: { x: 5, y: 0 }, width: 140, height: 80,
        health: 1000, maxHealth: 1000, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1000 + i * 800, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 50, maxHealth: 50, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ // Last enemy is Titan
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 500, maxHealth: 500, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      // Gray boss + 3 bots + 1 Titan (Last enemy)
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 400, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 100, maxHealth: 100, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2500, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 200, maxHealth: 200, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ // Last enemy is Titan
        id: 4, pos: { x: 3200, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      // Regular levels: 4 bots + 1 Titan
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 500, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2, y: 0 },
          width: 32, height: 48, health: 50 + level * 5, maxHealth: 50 + level * 5, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 200 + level * 20, maxHealth: 200 + level * 20, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      // Physics - All robots on ground
      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      // Vertical movement only for jumping
      const canJump = true; 
      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded && canJump) {
        player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
        player.grounded = false;
      }
      player.vel.y += GRAVITY;

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Allies stay on ground
      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.08;
        ally.pos.y = floorY - 48; 
      });

      // Shooting
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 15 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 12, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      // Update bullets
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) { currentKills++; return; }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 40) enemy.pos.x = player.pos.x - 40;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.01) enemy.vel.x *= -1;
        }

        const isBossEnemy = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossEnemy ? 800 : 400;
        const cooldown = enemy.type === 'tank' ? 35 : (isBossEnemy ? 50 : 70);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 9, y: 0 }, width: 20, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 20
            });
          } else if (isBossEnemy) {
            for (let angle = -2; angle <= 2; angle += 2) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 30 },
                vel: { x: dir * 7, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        // Collision: Player bullets vs Enemy
        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        // Collision: Player vs Enemy (Ramming)
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 6) {
             enemy.health -= isBossEnemy ? 10 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.3;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossEnemy ? 30 : 10;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      // Collision: Enemy bullets vs Player
      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.4 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        if (currentKills >= 5) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      // BACKGROUND - Burning Buildings
      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a25', '#101030'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.15;
        const offsetX = -(cameraX * speed) % 400;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 400; x += 250) {
          const h = 260 + (i * 60) + Math.sin(x/50) * 40;
          const buildX = x;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(buildX, buildY, 180, h);

          if ((buildX + e.frame) % 200 < 80) {
            ctx.fillStyle = e.frame % 14 < 7 ? '#ee3300' : '#ffaa00';
            ctx.beginPath();
            const fX = buildX + 30 + Math.random() * 120;
            const fY = buildY + 20 + Math.random() * 40;
            ctx.arc(fX, fY, 10 + Math.random()*10, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(40, 40, 50, 0.4)';
            ctx.beginPath();
            ctx.arc(fX, fY - 40 - (e.frame % 40), 20, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      // Draw Allies
      allies.forEach(ally => {
        ctx.save();
        ctx.translate(ally.pos.x - cameraX, ally.pos.y);
        ctx.fillStyle = '#005577';
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = '#00ccff'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = '#ffffff'; ctx.fillRect(8, 8, 16, 8);
        ctx.restore();
      });

      // Draw Enemies
      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222222';
          ctx.fillRect(0, 20, 140, 60);
          ctx.fillRect(40, 0, 80, 40);
          ctx.fillStyle = '#000000';
          ctx.fillRect(120, 15, 60, 15);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(50, 10, 20, 20);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#666666';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#999999'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 6);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#300010'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        // Health bar
        ctx.fillStyle = '#220000'; ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      // Draw Player
      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);
      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = upgrades.robotTier > 0 ? '#00ccff' : '#00f3ff';
        if (upgrades.robotTier >= 2) ctx.fillStyle = '#66ffcc';
        ctx.fillRect(0, 0, 32, 48);
        ctx.fillStyle = '#0066ff'; ctx.fillRect(4, 4, 24, 16);
        ctx.fillStyle = 'white'; ctx.fillRect(10, 8, 12, 4);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00ccff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(48, 12); ctx.lineTo(32, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0066ff'; ctx.beginPath();
        ctx.moveTo(10, 0); ctx.lineTo(25, -10); ctx.lineTo(35, 0); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        ctx.fillStyle = '#003366'; ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = '#00ffff'; ctx.fillRect(12, 12, 40, 20); 
        ctx.fillStyle = '#ffcc00'; ctx.fillRect(10, 45, 12, 12); ctx.fillRect(42, 45, 12, 12);
      }
      ctx.restore();

      // Bullets
      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'ROBOTIC ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'GROUND-STRIKE JET' : 'ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-cyan-400' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-blue-200';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>MODE: {modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Stability Sync</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(modeFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            {level === 5 ? (
              <>
                <div className="text-xs text-yellow-500 font-bold uppercase mb-1">ESCAPE DISTANCE</div>
                <div className="text-xl font-black text-white">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
                <div className="flex gap-1 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-bold text-xl font-mono">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD] Ground Move</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Robot [C] Car (30s) [J] Ground-Jet (30s)</div>
        {level >= 2 && <div className="text-cyan-400 font-bold">[K] TITAN COMBINE (60s)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"/>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 9; 
const PLAYER_SPEED_TITAN = 3; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -12;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

// Robot squad colors: 1st Red (Player), 2nd Black, 3rd Green, 4th White, 5th Blue
const SQUAD_COLORS = ['#ff0000', '#1a1a1a', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies (Robots 2-5)
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -70 - i * 50, y: 0 },
          color: SQUAD_COLORS[i + 1] // Index 1, 2, 3, 4
        });
      }
    }

    const enemies: Enemy[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      // Tank + 3 bots + 1 Titan (Last enemy)
      enemies.push({
        id: 0, pos: { x: -500, y: floorY - 80 }, vel: { x: 5, y: 0 }, width: 140, height: 80,
        health: 1000, maxHealth: 1000, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1000 + i * 800, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 50, maxHealth: 50, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 500, maxHealth: 500, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      // Gray boss + 3 bots + 1 Titan (Last enemy)
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 400, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 100, maxHealth: 100, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2500, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 200, maxHealth: 200, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ 
        id: 4, pos: { x: 3200, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      // Regular levels: 4 bots + 1 Titan
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 500, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2, y: 0 },
          width: 32, height: 48, health: 50 + level * 5, maxHealth: 50 + level * 5, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 200 + level * 20, maxHealth: 200 + level * 20, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
        player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
        player.grounded = false;
      }
      player.vel.y += GRAVITY;

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Allies
      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.08;
        ally.pos.y = floorY - 48; 
      });

      // Shooting
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 15 : (currentMode === PlayerMode.TITAN ? 25 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 14, y: i * 2 },
              width: 16, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: 60
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 12, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 25
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) { currentKills++; return; }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 40) enemy.pos.x = player.pos.x - 40;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.01) enemy.vel.x *= -1;
        }

        const isBossEnemy = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossEnemy ? 800 : 400;
        const cooldown = enemy.type === 'tank' ? 35 : (isBossEnemy ? 50 : 70);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 9, y: 0 }, width: 20, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 20
            });
          } else if (isBossEnemy) {
            for (let angle = -2; angle <= 2; angle += 2) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 30 },
                vel: { x: dir * 7, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 15
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 5, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 5
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 6) {
             enemy.health -= isBossEnemy ? 10 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.3;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossEnemy ? 30 : 10;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.4 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        if (currentKills >= 5) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a25', '#101030'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.15;
        const offsetX = -(cameraX * speed) % 400;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 400; x += 250) {
          const h = 260 + (i * 60) + Math.sin(x/50) * 40;
          const buildX = x;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(buildX, buildY, 180, h);

          if ((buildX + e.frame) % 200 < 80) {
            ctx.fillStyle = e.frame % 14 < 7 ? '#ee3300' : '#ffaa00';
            ctx.beginPath();
            const fX = buildX + 30 + Math.random() * 120;
            const fY = buildY + 20 + Math.random() * 40;
            ctx.arc(fX, fY, 10 + Math.random()*10, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(40, 40, 50, 0.4)';
            ctx.beginPath();
            ctx.arc(fX, fY - 40 - (e.frame % 40), 20, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      // Draw Allies - specific colors if not in Titan mode
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = ally.color;
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = '#ffffff55'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = '#ffffffaa'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      // Draw Enemies
      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222222';
          ctx.fillRect(0, 20, 140, 60);
          ctx.fillRect(40, 0, 80, 40);
          ctx.fillStyle = '#000000';
          ctx.fillRect(120, 15, 60, 15);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(50, 10, 20, 20);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#666666';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#999999'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 6);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#300010'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -12, enemy.width, 6);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -12, (enemy.health / enemy.maxHealth) * enemy.width, 6);
        ctx.restore();
      });

      // Draw Player
      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = SQUAD_COLORS[0]; // Player is first robot: RED
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = 'white'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = '#ffffffaa'; ctx.fillRect(8, 8, 16, 8);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00ccff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(48, 12); ctx.lineTo(32, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0066ff'; ctx.beginPath();
        ctx.moveTo(10, 0); ctx.lineTo(25, -10); ctx.lineTo(35, 0); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-8, 2, 8, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        // Rainbow Titan
        const hue = (e.frame * 2) % 360;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = `hsl(${(hue + 180) % 360}, 100%, 70%)`;
        ctx.lineWidth = 4;
        ctx.strokeRect(4, 4, 56, 76);

        ctx.fillStyle = 'white';
        ctx.fillRect(12, 12, 40, 20); 

        // Rainbow glow effect
        ctx.shadowBlur = 20;
        ctx.shadowColor = `hsl(${hue}, 100%, 60%)`;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffcc00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 10 ? 15 : 10; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'CRIMSON ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'PATROL UNIT' : 
                   playerMode === PlayerMode.JET ? 'GROUND-STRIKE JET' : 'RAINBOW ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-red-500' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-300' : 'text-purple-400';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/60 border border-cyan-900 p-2 rounded backdrop-blur-sm">
            <div className="text-xs text-cyan-500 font-bold uppercase mb-1 flex justify-between">
              <span>Integrity</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-4 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
              <div className="h-full bg-gradient-to-r from-red-600 to-cyan-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-lg font-bold tracking-widest uppercase ${modeColor}`}>MODE: {modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-48 mt-1 bg-black/40 border border-blue-900 p-1">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5">Stability Sync</div>
                 <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-0.5">{Math.ceil(modeFramesLeft / 60)}s</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/60 border border-red-900 p-2 rounded backdrop-blur-sm text-right">
            {level === 5 ? (
              <>
                <div className="text-xs text-yellow-500 font-bold uppercase mb-1">ESCAPE DISTANCE</div>
                <div className="text-xl font-black text-white">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-xs text-red-500 font-bold uppercase mb-1">Hostiles Neutralized</div>
                <div className="flex gap-1 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-4 h-4 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_5px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-bold text-xl font-mono">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-500 font-mono space-y-1 bg-black/40 p-2 rounded border border-gray-900">
        <div>[WASD] Ground Move</div>
        <div>[SPACE] Attack / Jump</div>
        <div>[R] Red Robot [C] Car [J] Jet</div>
        {level >= 2 && <div className="text-purple-400 font-bold">[K] RAINBOW TITAN COMBINE (Requires Level 2)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_50px_rgba(0,0,0,1)]"/>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 11; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

// Robot squad colors: 
// 1st: Red (Player)
// 2nd: Black
// 3rd: Green
// 4th: White
// 5th: Blue
const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as Enemy[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    // Initialize allies based on colors provided: Black, Green, White, Blue
    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1] 
        });
      }
    }

    const enemies: Enemy[] = [];
    const floorY = 350 + 48;

    // Requirement: Last enemy (index 4) is always a Titan on every level.
    if (level === 5) {
      // Tank + 3 bots + 1 Titan (Last enemy)
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      // Gray boss + 3 bots + 1 Titan (Last enemy)
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 400, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2800, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 250, maxHealth: 250, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ 
        id: 4, pos: { x: 3500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 800, maxHealth: 800, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      // Regular levels: 4 bots + 1 Titan (Last enemy)
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      // Physics - Grounded for all modes as requested
      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      // Jumping
      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
        player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
        player.grounded = false;
      }
      player.vel.y += GRAVITY;

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Allies logic
      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      // Combat logic
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 12 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          // Rainbow Titan fires triple shots
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 16, y: i * 2.5 },
              width: 18, height: 9, owner: 'player', health: 1, maxHealth: 1, damage: 70
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
          });
        }
        player.lastShot = e.frame;
      }

      // Update bullets
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      enemies.forEach(enemy => {
        if (enemy.isDead) { currentKills++; return; }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 30) enemy.pos.x = player.pos.x - 30;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossUnit ? 900 : 450;
        const cooldown = enemy.type === 'tank' ? 30 : (isBossUnit ? 45 : 75);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 10, y: 0 }, width: 24, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 25
            });
          } else if (isBossUnit) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 35 },
                vel: { x: dir * 8, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 18
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 6
            });
          }
          enemy.lastShot = e.frame;
        }

        // Damage detection
        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        // Player collision
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 7) {
             enemy.health -= isBossUnit ? 15 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.4;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossUnit ? 35 : 12;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      });

      // Enemy bullets vs Player
      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.35 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      // Win condition
      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE || currentKills >= 5) onWin();
      } else {
        if (currentKills >= 5) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      // BACKGROUND
      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a22', '#12122d'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.18;
        const offsetX = -(cameraX * speed) % 500;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 500; x += 300) {
          const h = 280 + (i * 70) + Math.sin(x/60) * 50;
          const bW = 200;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(x, buildY, bW, h);

          if ((x + e.frame) % 250 < 100) {
            ctx.fillStyle = e.frame % 12 < 6 ? '#ff4400' : '#ffaa00';
            ctx.beginPath();
            const fX = x + 40 + Math.random() * 120;
            const fY = buildY + 15 + Math.random() * 45;
            ctx.arc(fX, fY, 12 + Math.random()*12, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(30, 30, 40, 0.45)';
            ctx.beginPath();
            ctx.arc(fX, fY - 50 - (e.frame % 50), 22, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      // Allies
      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = ally.color;
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      // Enemies
      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222';
          ctx.fillRect(0, 20, 150, 60);
          ctx.fillRect(45, 0, 85, 40);
          ctx.fillStyle = '#000';
          ctx.fillRect(130, 15, 70, 16);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(55, 10, 22, 22);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#777';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 8);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#330015'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -14, enemy.width, 8);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -14, (enemy.health / enemy.maxHealth) * enemy.width, 8);
        ctx.restore();
      });

      // Player
      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = SQUAD_COLORS[0]; // Player is RED
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = 'white'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(8, 8, 16, 8);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00eeff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(52, 12); ctx.lineTo(36, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0044ff'; ctx.beginPath();
        ctx.moveTo(12, 0); ctx.lineTo(28, -12); ctx.lineTo(40, 0); ctx.fill();
        ctx.fillStyle = '#ff9900'; ctx.fillRect(-10, 2, 10, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        // Rainbow Alpha Titan
        const hue = (e.frame * 4) % 360;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = `hsl(${(hue + 120) % 360}, 100%, 60%)`;
        ctx.lineWidth = 5;
        ctx.strokeRect(4, 4, 56, 76);

        ctx.fillStyle = 'white';
        ctx.fillRect(12, 12, 40, 22); 

        ctx.shadowBlur = 25;
        ctx.shadowColor = `hsl(${hue}, 100%, 65%)`;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffdd00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 12 ? 20 : 12; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'CRIMSON ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'HIGH-SPEED PATROL' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'RAINBOW ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-red-500' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-400' : 'text-fuchsia-400';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
            <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
              <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
              <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
              <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300 shadow-[0_0_10px_rgba(34,211,238,0.5)]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-xl font-black italic tracking-tighter uppercase ${modeColor} drop-shadow-[0_0_5px_rgba(0,0,0,1)]`}>{modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-56 mt-2 bg-black/60 border border-blue-900/50 p-1.5 rounded">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5 tracking-widest font-orbitron">SYNCHRONIZATION</div>
                 <div className="w-full h-1.5 bg-gray-950 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-1 font-bold">{Math.ceil(modeFramesLeft / 60)} SEC REMAINING</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/70 border border-red-900 p-2 rounded backdrop-blur-sm text-right min-w-[120px]">
            {level === 5 ? (
              <>
                <div className="text-[10px] text-yellow-500 font-bold uppercase mb-1 font-orbitron">EXTRACTION DISTANCE</div>
                <div className="text-2xl font-black text-white italic">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-[10px] text-red-500 font-bold uppercase mb-1 font-orbitron">SECTOR TARGETS</div>
                <div className="flex gap-1.5 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-5 h-5 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_8px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1 border-white shadow-inner' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-400 font-mono space-y-1 bg-black/60 p-3 rounded border border-gray-800 backdrop-blur-md">
        <div className="text-cyan-400 font-bold mb-1 uppercase tracking-widest border-b border-cyan-900 pb-1">Operational Inputs</div>
        <div>[WASD] Surface Navigation</div>
        <div>[SPACE] Combat / Propelled Jump</div>
        <div>[R] Crimson Robot [C] Car [J] Interceptor</div>
        {level >= 2 && <div className="text-fuchsia-400 font-bold animate-pulse mt-2">[K] COMBINE SQUAD (RAINBOW TITAN)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_80px_rgba(0,0,0,1)] bg-black rounded-lg"/>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 11; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1] 
        });
      }
    }

    const enemies: (Enemy & { hasSplit?: boolean })[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 400, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2800, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 250, maxHealth: 250, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ 
        id: 4, pos: { x: 3500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 800, maxHealth: 800, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
        player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
        player.grounded = false;
      }
      player.vel.y += GRAVITY;

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 12 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 16, y: i * 2.5 },
              width: 18, height: 9, owner: 'player', health: 1, maxHealth: 1, damage: 70
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      // We use a for loop because we might modify the array (Titan split)
      for (let i = 0; i < enemies.length; i++) {
        const enemy = enemies[i];
        if (enemy.isDead) { currentKills++; continue; }

        // SPECIAL: Titan Split Logic
        if (enemy.type === 'titan' && enemy.health < enemy.maxHealth * 0.25 && !enemy.hasSplit) {
          enemy.isDead = true;
          enemy.hasSplit = true;
          // Spawn 6 small robots at Titan's location
          for (let j = 0; j < 6; j++) {
            enemies.push({
              id: 500 + i * 10 + j,
              pos: { x: enemy.pos.x + (j - 3) * 20, y: enemy.pos.y + 20 },
              vel: { x: (Math.random() - 0.5) * 6, y: -4 - Math.random() * 4 },
              width: 32,
              height: 48,
              health: 50 + e.level * 5,
              maxHealth: 50 + e.level * 5,
              isDead: false,
              type: 'bot',
              lastShot: e.frame
            });
          }
          continue;
        }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 30) enemy.pos.x = player.pos.x - 30;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;

          // Bots logic for floor
          if (enemy.pos.y < floorY - enemy.height) {
            enemy.vel.y += GRAVITY;
            enemy.pos.y += enemy.vel.y;
          } else {
            enemy.pos.y = floorY - enemy.height;
            enemy.vel.y = 0;
          }
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossUnit ? 900 : 450;
        const cooldown = enemy.type === 'tank' ? 30 : (isBossUnit ? 45 : 75);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 10, y: 0 }, width: 24, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 25
            });
          } else if (isBossUnit) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 35 },
                vel: { x: dir * 8, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 18
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 6
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + effectiveHeight && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 7) {
             enemy.health -= isBossUnit ? 15 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.4;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossUnit ? 35 : 12;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      }

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.35 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      // Win Condition: All enemies dead, including those from split
      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        const allEnemiesEliminated = enemies.every(en => en.isDead);
        if (allEnemiesEliminated && enemies.length > 0) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a22', '#12122d'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.18;
        const offsetX = -(cameraX * speed) % 500;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 500; x += 300) {
          const h = 280 + (i * 70) + Math.sin(x/60) * 50;
          const bW = 200;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(x, buildY, bW, h);

          if ((x + e.frame) % 250 < 100) {
            ctx.fillStyle = e.frame % 12 < 6 ? '#ff4400' : '#ffaa00';
            ctx.beginPath();
            const fX = x + 40 + Math.random() * 120;
            const fY = buildY + 15 + Math.random() * 45;
            ctx.arc(fX, fY, 12 + Math.random()*12, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(30, 30, 40, 0.45)';
            ctx.beginPath();
            ctx.arc(fX, fY - 50 - (e.frame % 50), 22, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = ally.color;
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222';
          ctx.fillRect(0, 20, 150, 60);
          ctx.fillRect(45, 0, 85, 40);
          ctx.fillStyle = '#000';
          ctx.fillRect(130, 15, 70, 16);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(55, 10, 22, 22);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#777';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 8);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#330015'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -14, enemy.width, 8);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -14, (enemy.health / enemy.maxHealth) * enemy.width, 8);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = SQUAD_COLORS[0]; 
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = 'white'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(8, 8, 16, 8);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00eeff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(52, 12); ctx.lineTo(36, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0044ff'; ctx.beginPath();
        ctx.moveTo(12, 0); ctx.lineTo(28, -12); ctx.lineTo(40, 0); ctx.fill();
        ctx.fillStyle = '#ff9900'; ctx.fillRect(-10, 2, 10, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        const hue = (e.frame * 4) % 360;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = `hsl(${(hue + 120) % 360}, 100%, 60%)`;
        ctx.lineWidth = 5;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = 'white';
        ctx.fillRect(12, 12, 40, 22); 
        ctx.shadowBlur = 25;
        ctx.shadowColor = `hsl(${hue}, 100%, 65%)`;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffdd00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 12 ? 20 : 12; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'CRIMSON ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'HIGH-SPEED PATROL' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'RAINBOW ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-red-500' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-400' : 'text-fuchsia-400';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
            <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
              <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
              <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
              <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300 shadow-[0_0_10px_rgba(34,211,238,0.5)]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-xl font-black italic tracking-tighter uppercase ${modeColor} drop-shadow-[0_0_5px_rgba(0,0,0,1)]`}>{modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-56 mt-2 bg-black/60 border border-blue-900/50 p-1.5 rounded">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5 tracking-widest font-orbitron">SYNCHRONIZATION</div>
                 <div className="w-full h-1.5 bg-gray-950 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-1 font-bold">{Math.ceil(modeFramesLeft / 60)} SEC REMAINING</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/70 border border-red-900 p-2 rounded backdrop-blur-sm text-right min-w-[120px]">
            {level === 5 ? (
              <>
                <div className="text-[10px] text-yellow-500 font-bold uppercase mb-1 font-orbitron">EXTRACTION DISTANCE</div>
                <div className="text-2xl font-black text-white italic">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-[10px] text-red-500 font-bold uppercase mb-1 font-orbitron">SECTOR TARGETS</div>
                <div className="flex gap-1.5 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-5 h-5 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_8px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1 border-white shadow-inner' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-400 font-mono space-y-1 bg-black/60 p-3 rounded border border-gray-800 backdrop-blur-md">
        <div className="text-cyan-400 font-bold mb-1 uppercase tracking-widest border-b border-cyan-900 pb-1">Operational Inputs</div>
        <div>[WASD] Surface Navigation</div>
        <div>[SPACE] Combat / Propelled Jump</div>
        <div>[R] Crimson Robot [C] Car [J] Interceptor</div>
        {level >= 2 && <div className="text-fuchsia-400 font-bold animate-pulse mt-2">[K] COMBINE SQUAD (RAINBOW TITAN)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_80px_rgba(0,0,0,1)] bg-black rounded-lg"/>
    </div>
  );
};

