import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState(1);
  const [money, setMoney] = useState(0);
  const [upgrades, setUpgrades] = useState<Upgrades>({ robotTier: 0, weaponTier: 0 });
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSave, setHasSave] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  // Load progress on mount
  useEffect(() => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setHasSave(true);
      const savedLvl = parsed.level || 1;
      setLevel(savedLvl);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || savedLvl || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { robotTier: 0, weaponTier: 0 });
    }
  }, []);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  useEffect(() => {
    if (gameState !== GameState.MENU && gameState !== GameState.PAUSED && gameState !== GameState.LEVEL_SELECT) {
      const saveData = {
        level,
        maxUnlockedLevel,
        money,
        upgrades
      };
      localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    }
  }, [level, maxUnlockedLevel, money, upgrades, gameState]);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ robotTier: 0, weaponTier: 0 });
    startLevel(1);
  };

  const handleContinueGame = () => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      const targetLevel = parsed.level || 1;
      setLevel(targetLevel);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || targetLevel || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { robotTier: 0, weaponTier: 0 });
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    setMoney(prev => prev + 25);
    const completedLevel = level;
    const nextLvl = level + 1;

    if (nextLvl > maxUnlockedLevel) {
      setMaxUnlockedLevel(nextLvl);
    }

    if (completedLevel >= 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    startLevel(level);
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
      setHasSave(true);
    } else {
      handleNextLevel();
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobot = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeapon = () => {
    if (money >= 25) {
      setMoney(m => m - 25);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenLevelSelect={openLevelSelect}
          hasSave={hasSave} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase">
            Sector {level - 1} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: $25</div>
          <button 
            onClick={() => openShop(GameState.LEVEL_COMPLETE)}
            className="px-12 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 mb-4 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)]"
          >
            VISIT ARMORY
          </button>
          <button 
            onClick={handleNextLevel}
            className="px-12 py-3 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-sm transition-all w-64 uppercase tracking-wider"
          >
            Deploy to Sector {level}
          </button>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobot} 
          onBuyWeapon={buyWeapon} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => {
          localStorage.removeItem(SAVE_KEY);
          setHasSave(false);
          setGameState(GameState.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 12; // Increased for better interceptor feel
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1] 
        });
      }
    }

    const enemies: (Enemy & { hasSplit?: boolean })[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 400, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2800, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 250, maxHealth: 250, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ 
        id: 4, pos: { x: 3500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 800, maxHealth: 800, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      // Horizontal movement
      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
      } else {
        player.vel.x *= 0.8;
      }

      // Vertical movement & Gravity logic
      if (currentMode === PlayerMode.JET) {
        // FLYING LOGIC: Full 2D control, no gravity
        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -speed;
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = speed;
        } else {
          player.vel.y *= 0.8; // Smooth dampening
        }
        player.grounded = false;
      } else {
        // GROUNDED LOGIC: Jumping and gravity
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      // Vertical collision and clamping
      if (currentMode === PlayerMode.JET) {
        // Flight bounds check
        if (player.pos.y < 0) {
          player.pos.y = 0;
          player.vel.y = 0;
        }
        if (player.pos.y > floorY - effectiveHeight) {
          player.pos.y = floorY - effectiveHeight;
          player.vel.y = 0;
          player.grounded = true;
        }
      } else {
        // Traditional ground collision
        if (player.pos.y > floorY - effectiveHeight) {
          player.pos.y = floorY - effectiveHeight;
          player.vel.y = 0;
          player.grounded = true;
        }
      }

      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Ally positioning
      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      // Weapon firing
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 10 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      // Space attack logic - Jet can fly and shoot simultaneously
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 16, y: i * 2.5 },
              width: 18, height: 9, owner: 'player', health: 1, maxHealth: 1, damage: 70
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      for (let i = 0; i < enemies.length; i++) {
        const enemy = enemies[i];
        if (enemy.isDead) { currentKills++; continue; }

        if (enemy.type === 'titan' && enemy.health < enemy.maxHealth * 0.25 && !enemy.hasSplit) {
          enemy.isDead = true;
          enemy.hasSplit = true;
          for (let j = 0; j < 6; j++) {
            enemies.push({
              id: 500 + i * 10 + j,
              pos: { x: enemy.pos.x + (j - 3) * 20, y: enemy.pos.y + 20 },
              vel: { x: (Math.random() - 0.5) * 6, y: -4 - Math.random() * 4 },
              width: 32,
              height: 48,
              health: 50 + e.level * 5,
              maxHealth: 50 + e.level * 5,
              isDead: false,
              type: 'bot',
              lastShot: e.frame
            });
          }
          continue;
        }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 30) enemy.pos.x = player.pos.x - 30;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;

          if (enemy.pos.y < floorY - enemy.height) {
            enemy.vel.y += GRAVITY;
            enemy.pos.y += enemy.vel.y;
          } else {
            enemy.pos.y = floorY - enemy.height;
            enemy.vel.y = 0;
          }
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossUnit ? 900 : 450;
        const cooldown = enemy.type === 'tank' ? 30 : (isBossUnit ? 45 : 75);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 10, y: 0 }, width: 24, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 25
            });
          } else if (isBossUnit) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 35 },
                vel: { x: dir * 8, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 18
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 6
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 7) {
             enemy.health -= isBossUnit ? 15 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.4;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossUnit ? 35 : 12;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      }

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.35 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        const allEnemiesEliminated = enemies.every(en => en.isDead);
        if (allEnemiesEliminated && enemies.length > 0) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a22', '#12122d'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.18;
        const offsetX = -(cameraX * speed) % 500;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 500; x += 300) {
          const h = 280 + (i * 70) + Math.sin(x/60) * 50;
          const bW = 200;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(x, buildY, bW, h);

          if ((x + e.frame) % 250 < 100) {
            ctx.fillStyle = e.frame % 12 < 6 ? '#ff4400' : '#ffaa00';
            ctx.beginPath();
            const fX = x + 40 + Math.random() * 120;
            const fY = buildY + 15 + Math.random() * 45;
            ctx.arc(fX, fY, 12 + Math.random()*12, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(30, 30, 40, 0.45)';
            ctx.beginPath();
            ctx.arc(fX, fY - 50 - (e.frame % 50), 22, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = ally.color;
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222';
          ctx.fillRect(0, 20, 150, 60);
          ctx.fillRect(45, 0, 85, 40);
          ctx.fillStyle = '#000';
          ctx.fillRect(130, 15, 70, 16);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(55, 10, 22, 22);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#777';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 8);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#330015'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -14, enemy.width, 8);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -14, (enemy.health / enemy.maxHealth) * enemy.width, 8);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = SQUAD_COLORS[0]; 
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = 'white'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(8, 8, 16, 8);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00eeff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(52, 12); ctx.lineTo(36, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0044ff'; ctx.beginPath();
        ctx.moveTo(12, 0); ctx.lineTo(28, -12); ctx.lineTo(40, 0); ctx.fill();
        ctx.fillStyle = '#ff9900'; ctx.fillRect(-10, 2, 10, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        const hue = (e.frame * 4) % 360;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = `hsl(${(hue + 120) % 360}, 100%, 60%)`;
        ctx.lineWidth = 5;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = 'white';
        ctx.fillRect(12, 12, 40, 22); 
        ctx.shadowBlur = 25;
        ctx.shadowColor = `hsl(${hue}, 100%, 65%)`;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffdd00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 12 ? 20 : 12; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'CRIMSON ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'HIGH-SPEED PATROL' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'RAINBOW ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-red-500' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-400' : 'text-fuchsia-400';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
            <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
              <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
              <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
              <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300 shadow-[0_0_10px_rgba(34,211,238,0.5)]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-xl font-black italic tracking-tighter uppercase ${modeColor} drop-shadow-[0_0_5px_rgba(0,0,0,1)]`}>{modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-56 mt-2 bg-black/60 border border-blue-900/50 p-1.5 rounded">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5 tracking-widest font-orbitron">SYNCHRONIZATION</div>
                 <div className="w-full h-1.5 bg-gray-950 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-1 font-bold">{Math.ceil(modeFramesLeft / 60)} SEC REMAINING</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/70 border border-red-900 p-2 rounded backdrop-blur-sm text-right min-w-[120px]">
            {level === 5 ? (
              <>
                <div className="text-[10px] text-yellow-500 font-bold uppercase mb-1 font-orbitron">EXTRACTION DISTANCE</div>
                <div className="text-2xl font-black text-white italic">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-[10px] text-red-500 font-bold uppercase mb-1 font-orbitron">SECTOR TARGETS</div>
                <div className="flex gap-1.5 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-5 h-5 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_8px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1 border-white shadow-inner' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-400 font-mono space-y-1 bg-black/60 p-3 rounded border border-gray-800 backdrop-blur-md">
        <div className="text-cyan-400 font-bold mb-1 uppercase tracking-widest border-b border-cyan-900 pb-1">Operational Inputs</div>
        <div>[WASD / ARROWS] {playerMode === PlayerMode.JET ? 'Flight Navigation' : 'Surface Navigation'}</div>
        <div>[SPACE] Combat {playerMode !== PlayerMode.JET && '/ Propelled Jump'}</div>
        <div>[R] Crimson Robot [C] Car [J] Interceptor</div>
        {level >= 2 && <div className="text-fuchsia-400 font-bold animate-pulse mt-2">[K] COMBINE SQUAD (RAINBOW TITAN)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_80px_rgba(0,0,0,1)] bg-black rounded-lg"/>
    </div>
  );
};

export default GameView;

class SoundService {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  playShoot() {
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'square';
    osc.frequency.setValueAtTime(880, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(110, ctx.currentTime + 0.1);

    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.1);
  }

  playDrive(intensity: number = 1) {
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(40 + (intensity * 20), ctx.currentTime);

    gain.gain.setValueAtTime(0.03 * intensity, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.05);
  }

  playFly() {
    const ctx = this.init();
    const bufferSize = ctx.sampleRate * 0.1;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }

    const noise = ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(1200, ctx.currentTime);
    filter.Q.setValueAtTime(1, ctx.currentTime);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.05, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);

    noise.start();
  }

  playLose() {
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'square';
    osc.frequency.setValueAtTime(220, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(110, ctx.currentTime + 0.4);

    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.5);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.5);
  }

  playVictory() {
    const ctx = this.init();
    const playNote = (freq: number, startTime: number, duration: number, volume: number = 0.1) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, startTime);
      gain.gain.setValueAtTime(0, startTime);
      gain.gain.linearRampToValueAtTime(volume, startTime + 0.05);
      gain.gain.linearRampToValueAtTime(0, startTime + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(startTime);
      osc.stop(startTime + duration);
    };

    const notes = [261.63, 329.63, 392.00, 523.25]; // C Major arpeggio
    const duration = 6;
    const tempo = 0.2;

    for (let i = 0; i < duration / tempo; i++) {
      const note = notes[i % notes.length];
      playNote(note * (1 + Math.floor(i / notes.length) * 0.5), ctx.currentTime + (i * tempo), tempo, 0.08);
    }
  }
}

export const soundService = new SoundService();

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 12; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; // 60 seconds
const MODE_DURATION_FRAMES = 30 * 60; // 30 seconds for Jet and Car
const LEVEL_5_DISTANCE = 4000; 

const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.bullets = [];
    e.cameraX = 0;
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1] 
        });
      }
    }

    const enemies: (Enemy & { hasSplit?: boolean })[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      for (let i = 0; i < 3; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 400, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 3, pos: { x: 2800, y: floorY - 64 }, vel: { x: 0, y: 0 }, width: 48, height: 64,
        health: 250, maxHealth: 250, isDead: false, type: 'gray_boss', lastShot: 0
      });
      enemies.push({ 
        id: 4, pos: { x: 3500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 800, maxHealth: 800, isDead: false, type: 'titan', lastShot: 0
      });
    } else {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') {
        setPlayerMode(PlayerMode.ROBOT);
        engineRef.current.player.modeTimer = 0;
      }
      if (e.code === 'KeyC') {
        setPlayerMode(PlayerMode.CAR);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyJ') {
        setPlayerMode(PlayerMode.JET);
        engineRef.current.player.modeTimer = MODE_DURATION_FRAMES;
      }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      if (currentMode !== PlayerMode.ROBOT) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      // Horizontal movement
      if (keys['ArrowRight'] || keys['KeyD']) {
        player.vel.x = speed;
        player.facing = 1;
        if (currentMode === PlayerMode.CAR && e.frame % 5 === 0) soundService.playDrive(1.2);
        if (currentMode === PlayerMode.JET && e.frame % 4 === 0) soundService.playFly();
      } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vel.x = -speed;
        player.facing = -1;
        if (currentMode === PlayerMode.CAR && e.frame % 5 === 0) soundService.playDrive(1.2);
        if (currentMode === PlayerMode.JET && e.frame % 4 === 0) soundService.playFly();
      } else {
        player.vel.x *= 0.8;
      }

      // Vertical movement & Gravity logic
      if (currentMode === PlayerMode.JET) {
        if (keys['ArrowUp'] || keys['KeyW']) {
          player.vel.y = -speed;
          if (e.frame % 4 === 0) soundService.playFly();
        } else if (keys['ArrowDown'] || keys['KeyS']) {
          player.vel.y = speed;
          if (e.frame % 4 === 0) soundService.playFly();
        } else {
          player.vel.y *= 0.8; 
        }
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = 48;
      if (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) effectiveHeight = 24;
      if (currentMode === PlayerMode.TITAN) effectiveHeight = 84;

      if (currentMode === PlayerMode.JET) {
        if (player.pos.y < 0) {
          player.pos.y = 0;
          player.vel.y = 0;
        }
        if (player.pos.y > floorY - effectiveHeight) {
          player.pos.y = floorY - effectiveHeight;
          player.vel.y = 0;
          player.grounded = true;
        }
      } else {
        if (player.pos.y > floorY - effectiveHeight) {
          player.pos.y = floorY - effectiveHeight;
          player.vel.y = 0;
          player.grounded = true;
        }
      }

      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      allies.forEach((ally) => {
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 10 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      if (keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = 15;
        if (currentMode === PlayerMode.JET) shotYOffset = 10;
        if (currentMode === PlayerMode.CAR) shotYOffset = 20;
        if (currentMode === PlayerMode.TITAN) shotYOffset = 30;

        soundService.playShoot();

        if (currentMode === PlayerMode.TITAN) {
          for (let i = -1; i <= 1; i++) {
            bullets.push({
              pos: { x: player.pos.x + (player.facing === 1 ? 64 : 0), y: player.pos.y + shotYOffset + (i * 20) },
              vel: { x: player.facing * 16, y: i * 2.5 },
              width: 18, height: 9, owner: 'player', health: 1, maxHealth: 1, damage: 70
            });
          }
        } else {
          bullets.push({
            pos: { x: player.pos.x + (player.facing === 1 ? (currentMode === PlayerMode.ROBOT ? 32 : 48) : 0), y: player.pos.y + shotYOffset },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let currentKills = 0;
      for (let i = 0; i < enemies.length; i++) {
        const enemy = enemies[i];
        if (enemy.isDead) { currentKills++; continue; }

        if (enemy.type === 'titan' && enemy.health < enemy.maxHealth * 0.25 && !enemy.hasSplit) {
          enemy.isDead = true;
          enemy.hasSplit = true;
          for (let j = 0; j < 6; j++) {
            enemies.push({
              id: 500 + i * 10 + j,
              pos: { x: enemy.pos.x + (j - 3) * 20, y: enemy.pos.y + 20 },
              vel: { x: (Math.random() - 0.5) * 6, y: -4 - Math.random() * 4 },
              width: 32,
              height: 48,
              health: 50 + e.level * 5,
              maxHealth: 50 + e.level * 5,
              isDead: false,
              type: 'bot',
              lastShot: e.frame
            });
          }
          continue;
        }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.x > player.pos.x - 30) enemy.pos.x = player.pos.x - 30;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;

          if (enemy.pos.y < floorY - enemy.height) {
            enemy.vel.y += GRAVITY;
            enemy.pos.y += enemy.vel.y;
          } else {
            enemy.pos.y = floorY - enemy.height;
            enemy.vel.y = 0;
          }
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        const attackRange = isBossUnit ? 900 : 450;
        const cooldown = enemy.type === 'tank' ? 30 : (isBossUnit ? 45 : 75);

        if (Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > cooldown) {
          const dir = Math.sign(player.pos.x - enemy.pos.x);
          if (enemy.type === 'tank') {
            bullets.push({
              pos: { x: enemy.pos.x + enemy.width, y: enemy.pos.y + 20 },
              vel: { x: 10, y: 0 }, width: 24, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 25
            });
          } else if (isBossUnit) {
            for (let angle = -3; angle <= 3; angle += 3) {
              bullets.push({
                pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 35 },
                vel: { x: dir * 8, y: angle }, width: 14, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 18
              });
            }
          } else {
            bullets.push({
              pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : 0), y: enemy.pos.y + 15 },
              vel: { x: dir * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 6
            });
          }
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player') {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0) enemy.isDead = true;
            }
          }
        });

        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (player.pos.x < enemy.pos.x + enemy.width && player.pos.x + pWidth > enemy.pos.x &&
            player.pos.y < enemy.pos.y + enemy.height && player.pos.y + effectiveHeight > enemy.pos.y) {
          if (currentMode === PlayerMode.CAR && Math.abs(player.vel.x) > 7) {
             enemy.health -= isBossUnit ? 15 : 100;
             if (enemy.health <= 0) enemy.isDead = true;
             player.vel.x = -player.vel.x * 0.4;
          } else if (player.invulnerable <= 0) {
            setHealth(h => {
              const dmg = isBossUnit ? 35 : 12;
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            player.invulnerable = 60;
          }
        }
      }

      bullets.forEach((b, bIdx) => {
        const pWidth = (currentMode === PlayerMode.ROBOT) ? 32 : (currentMode === PlayerMode.TITAN ? 64 : 48);
        if (b.owner === 'enemy' && player.invulnerable <= 0) {
          if (b.pos.x < player.pos.x + pWidth && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + effectiveHeight && b.pos.y + b.height > player.pos.y) {
            setHealth(h => {
              const dmg = currentMode === PlayerMode.TITAN ? (b.damage || 5) * 0.35 : (b.damage || 5);
              const newH = Math.max(0, h - dmg);
              if (newH === 0) onDie();
              return newH;
            });
            bullets.splice(bIdx, 1);
            player.invulnerable = 20;
          }
        }
      });

      if (player.invulnerable > 0) player.invulnerable--;
      setKills(currentKills);

      if (curLevel === 5) {
        if (player.pos.x >= LEVEL_5_DISTANCE) onWin();
      } else {
        const allEnemiesEliminated = enemies.every(en => en.isDead);
        if (allEnemiesEliminated && enemies.length > 0) onWin();
      }

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;
      const currentMode = e.mode;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const buildColors = ['#08081a', '#0a0a22', '#12122d'];
      for (let i = 0; i < 3; i++) {
        const speed = (i + 1) * 0.18;
        const offsetX = -(cameraX * speed) % 500;
        ctx.fillStyle = buildColors[i];
        for (let x = offsetX; x < CANVAS_WIDTH + 500; x += 300) {
          const h = 280 + (i * 70) + Math.sin(x/60) * 50;
          const bW = 200;
          const buildY = CANVAS_HEIGHT - h - 52;
          ctx.fillRect(x, buildY, bW, h);

          if ((x + e.frame) % 250 < 100) {
            ctx.fillStyle = e.frame % 12 < 6 ? '#ff4400' : '#ffaa00';
            ctx.beginPath();
            const fX = x + 40 + Math.random() * 120;
            const fY = buildY + 15 + Math.random() * 45;
            ctx.arc(fX, fY, 12 + Math.random()*12, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = 'rgba(30, 30, 40, 0.45)';
            ctx.beginPath();
            ctx.arc(fX, fY - 50 - (e.frame % 50), 22, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = buildColors[i];
          }
        }
      }

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, floorY, CANVAS_WIDTH, 2);

      if (currentMode !== PlayerMode.TITAN) {
        allies.forEach(ally => {
          ctx.save();
          ctx.translate(ally.pos.x - cameraX, ally.pos.y);
          ctx.fillStyle = ally.color;
          ctx.fillRect(0, 0, 32, 48);
          ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1;
          ctx.strokeRect(2, 2, 28, 44);
          ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(8, 8, 16, 8);
          ctx.restore();
        });
      }

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        const isBossVisual = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'gray_boss';
        ctx.save();
        ctx.translate(enemy.pos.x - cameraX, enemy.pos.y);

        if (enemy.type === 'tank') {
          ctx.fillStyle = '#222';
          ctx.fillRect(0, 20, 150, 60);
          ctx.fillRect(45, 0, 85, 40);
          ctx.fillStyle = '#000';
          ctx.fillRect(130, 15, 70, 16);
          ctx.fillStyle = '#ff0000';
          ctx.fillRect(55, 10, 22, 22);
        } else if (enemy.type === 'gray_boss') {
          ctx.fillStyle = '#777';
          ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
          ctx.strokeRect(2, 2, enemy.width-4, enemy.height-4);
          ctx.fillStyle = '#ff0000'; ctx.fillRect(10, 10, 28, 8);
        } else if (enemy.type === 'titan') {
          ctx.fillStyle = '#330015'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.strokeStyle = '#ff0055'; ctx.lineWidth = 2; ctx.strokeRect(4, 4, enemy.width-8, enemy.height-8);
          ctx.fillStyle = '#ff0055'; ctx.fillRect(15, 20, 34, 15);
        } else {
          ctx.fillStyle = '#ff0055'; ctx.fillRect(0, 0, enemy.width, enemy.height);
          ctx.fillStyle = '#ffffff'; ctx.fillRect(5, 10, 5, 5); ctx.fillRect(22, 10, 5, 5);
        }

        ctx.fillStyle = '#220000'; ctx.fillRect(0, -14, enemy.width, 8);
        ctx.fillStyle = isBossVisual ? '#ff00ff' : '#ff0000';
        ctx.fillRect(0, -14, (enemy.health / enemy.maxHealth) * enemy.width, 8);
        ctx.restore();
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.translate(player.pos.x - cameraX, player.pos.y);

      if (currentMode === PlayerMode.ROBOT) {
        ctx.fillStyle = SQUAD_COLORS[0]; 
        ctx.fillRect(0, 0, 32, 48);
        ctx.strokeStyle = 'white'; ctx.lineWidth = 1;
        ctx.strokeRect(2, 2, 28, 44);
        ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(8, 8, 16, 8);
      } else if (currentMode === PlayerMode.CAR) {
        ctx.fillStyle = '#0066ff'; ctx.fillRect(0, 0, 48, 24);
        ctx.fillStyle = '#000000'; ctx.fillRect(5, 16, 8, 8); ctx.fillRect(35, 16, 8, 8);
        ctx.fillStyle = e.frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(16, -8, 16, 8);
      } else if (currentMode === PlayerMode.JET) {
        ctx.fillStyle = '#00eeff'; ctx.beginPath();
        ctx.moveTo(0, 12); ctx.lineTo(52, 12); ctx.lineTo(36, 0); ctx.lineTo(0, 0); ctx.fill();
        ctx.fillStyle = '#0044ff'; ctx.beginPath();
        ctx.moveTo(12, 0); ctx.lineTo(28, -12); ctx.lineTo(40, 0); ctx.fill();
        ctx.fillStyle = '#ff9900'; ctx.fillRect(-10, 2, 10, 8);
      } else if (currentMode === PlayerMode.TITAN) {
        const hue = (e.frame * 4) % 360;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(0, 0, 64, 84);
        ctx.strokeStyle = `hsl(${(hue + 120) % 360}, 100%, 60%)`;
        ctx.lineWidth = 5;
        ctx.strokeRect(4, 4, 56, 76);
        ctx.fillStyle = 'white';
        ctx.fillRect(12, 12, 40, 22); 
        ctx.shadowBlur = 25;
        ctx.shadowColor = `hsl(${hue}, 100%, 65%)`;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? (upgrades.weaponTier > 0 ? '#ffdd00' : '#00f3ff') : '#ff0055';
        ctx.shadowBlur = b.width > 12 ? 20 : 12; ctx.shadowColor = ctx.fillStyle;
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  const modeName = playerMode === PlayerMode.ROBOT ? 'CRIMSON ENFORCER' : 
                   playerMode === PlayerMode.CAR ? 'HIGH-SPEED PATROL' : 
                   playerMode === PlayerMode.JET ? 'AERIAL INTERCEPTOR' : 'RAINBOW ALPHA TITAN';
  const modeColor = playerMode === PlayerMode.ROBOT ? 'text-red-500' : 
                    playerMode === PlayerMode.CAR ? 'text-blue-500' : 
                    playerMode === PlayerMode.JET ? 'text-cyan-400' : 'text-fuchsia-400';

  const maxTimer = playerMode === PlayerMode.TITAN ? TITAN_DURATION_FRAMES : MODE_DURATION_FRAMES;

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
        <div className="flex flex-col gap-2">
          <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
            <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
              <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
              <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
              <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300 shadow-[0_0_10px_rgba(34,211,238,0.5)]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          <div className="flex flex-col">
            <div className={`text-xl font-black italic tracking-tighter uppercase ${modeColor} drop-shadow-[0_0_5px_rgba(0,0,0,1)]`}>{modeName}</div>
            {playerMode !== PlayerMode.ROBOT && (
              <div className="w-56 mt-2 bg-black/60 border border-blue-900/50 p-1.5 rounded">
                 <div className="text-[8px] text-blue-400 font-bold uppercase mb-0.5 tracking-widest font-orbitron">SYNCHRONIZATION</div>
                 <div className="w-full h-1.5 bg-gray-950 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)] transition-all duration-100" style={{ width: `${(modeFramesLeft / maxTimer) * 100}%` }}></div>
                 </div>
                 <div className="text-[10px] text-right text-blue-300 font-mono mt-1 font-bold">{Math.ceil(modeFramesLeft / 60)} SEC REMAINING</div>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
          <div className="bg-black/70 border border-red-900 p-2 rounded backdrop-blur-sm text-right min-w-[120px]">
            {level === 5 ? (
              <>
                <div className="text-[10px] text-yellow-500 font-bold uppercase mb-1 font-orbitron">EXTRACTION DISTANCE</div>
                <div className="text-2xl font-black text-white italic">{Math.floor(distance)} / {LEVEL_5_DISTANCE}m</div>
              </>
            ) : (
              <>
                <div className="text-[10px] text-red-500 font-bold uppercase mb-1 font-orbitron">SECTOR TARGETS</div>
                <div className="flex gap-1.5 justify-end">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-5 h-5 rounded-sm border ${i < kills ? 'bg-red-600 border-red-400 shadow-[0_0_8px_red]' : 'bg-gray-800 border-gray-700'} ${i === 4 ? 'scale-125 mx-1 border-white shadow-inner' : ''}`}></div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30">SECTOR {level} / 20</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-4 text-[10px] text-gray-400 font-mono space-y-1 bg-black/60 p-3 rounded border border-gray-800 backdrop-blur-md">
        <div className="text-cyan-400 font-bold mb-1 uppercase tracking-widest border-b border-cyan-900 pb-1">Operational Inputs</div>
        <div>[WASD / ARROWS] {playerMode === PlayerMode.JET ? 'Flight Navigation' : 'Surface Navigation'}</div>
        <div>[SPACE] Combat {playerMode !== PlayerMode.JET && '/ Propelled Jump'}</div>
        <div>[R] Crimson Robot [C] Car [J] Interceptor</div>
        {level >= 2 && <div className="text-fuchsia-400 font-bold animate-pulse mt-2">[K] COMBINE SQUAD (RAINBOW TITAN)</div>}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video shadow-[0_0_80px_rgba(0,0,0,1)] bg-black rounded-lg"/>
    </div>
  );
};

export default GameView;

