import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState(1);
  const [money, setMoney] = useState(0);
  const [upgrades, setUpgrades] = useState<Upgrades>({ robotTier: 0, weaponTier: 0 });
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSave, setHasSave] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  // Load progress on mount
  useEffect(() => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setHasSave(true);
      const savedLvl = parsed.level || 1;
      setLevel(savedLvl);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || savedLvl || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { robotTier: 0, weaponTier: 0 });
    }
  }, []);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  useEffect(() => {
    if (gameState !== GameState.MENU && gameState !== GameState.PAUSED && gameState !== GameState.LEVEL_SELECT) {
      const saveData = {
        level,
        maxUnlockedLevel,
        money,
        upgrades
      };
      localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    }
  }, [level, maxUnlockedLevel, money, upgrades, gameState]);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ robotTier: 0, weaponTier: 0 });
    startLevel(1);
  };

  const handleContinueGame = () => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      const targetLevel = parsed.level || 1;
      setLevel(targetLevel);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || targetLevel || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { robotTier: 0, weaponTier: 0 });
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    setMoney(prev => prev + 25);
    const completedLevel = level;
    const nextLvl = level + 1;

    if (nextLvl > maxUnlockedLevel) {
      setMaxUnlockedLevel(nextLvl);
    }

    if (completedLevel >= 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    startLevel(level);
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
      setHasSave(true);
    } else {
      handleNextLevel();
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobot = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeapon = () => {
    if (money >= 25) {
      setMoney(m => m - 25);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenLevelSelect={openLevelSelect}
          hasSave={hasSave} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase">
            Sector {level - 1} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: $25</div>
          <button 
            onClick={() => openShop(GameState.LEVEL_COMPLETE)}
            className="px-12 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 mb-4 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)] font-orbitron uppercase"
          >
            VISIT ARMORY
          </button>
          <button 
            onClick={handleNextLevel}
            className="px-12 py-3 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-sm transition-all w-64 uppercase tracking-wider font-orbitron"
          >
            Deploy to Sector {level}
          </button>
          <button 
            onClick={() => {
              setGameState(GameState.MENU);
              setHasSave(true);
            }}
            className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-8 border border-gray-800 hover:border-gray-400 bg-gray-950/40"
          >
            Return to HQ
          </button>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobot} 
          onBuyWeapon={buyWeapon} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => {
          localStorage.removeItem(SAVE_KEY);
          setHasSave(false);
          setGameState(GameState.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "This is an escape mission! The player must run away from a giant shooting tank across a burning city.";
  if (level === 20) specialPrompt = "This is the final showdown against the dark gray Alpha Enforcer. It is smaller but more lethal than other bosses. Foreshadow a high personal cost for victory.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short cyberpunk mission briefing for Level ${level} of a robot police officer game. 
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the threat in the burning city.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini failed, using fallback briefing", error);
    return {
      level,
      title: level === 20 ? "The Final Enforcer" : (level === 5 ? "Death Chase" : `Sector ${level} Purge`),
      description: level === 5 
        ? "A massive siege tank is pursuing you. Reach the extraction point before you are pulverized." 
        : (level === 20 ? "The Rogue Alpha has been cornered. Neutralize the dark gray enforcer to end the war, but be prepared for its desperate final struggle." : "Hostile units detected in the burning sector. Cleanse the area."),
      threatLevel: level >= 15 ? "Extreme" : "High",
      enemyType: level === 5 ? "Siege Tank" : (level === 20 ? "Dark Alpha Enforcer" : "Rogue Battalion")
    };
  }
};

