import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 12; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; 
const MODE_DURATION_FRAMES = 30 * 60; 
const LEVEL_5_DISTANCE = 4000; 

const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);
  const [isCinematic, setIsCinematic] = useState(false);
  const [cinematicText, setCinematicText] = useState("");

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      lastAllyShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean; sequenceStage?: number; sequenceTimer?: number })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string; health: number; maxHealth: number; isDead: boolean }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level,
    cinematic: false,
    particles: [] as {x: number, y: number, vx: number, vy: number, life: number, color: string}[]
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.player.lastAllyShot = 0;
    e.bullets = [];
    e.cameraX = 0;
    e.cinematic = false;
    e.particles = [];
    setIsCinematic(false);
    setCinematicText("");
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1],
          health: 100,
          maxHealth: 100,
          isDead: false
        });
      }
    }

    const enemies: (Enemy & { hasSplit?: boolean; sequenceStage?: number; sequenceTimer?: number })[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 300, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 4, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
        health: 400, maxHealth: 400, isDead: false, type: 'dark_alpha', lastShot: 0,
        sequenceStage: 0, sequenceTimer: 0
      });
    } else {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (engineRef.current.cinematic) return;
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') { setPlayerMode(PlayerMode.ROBOT); engineRef.current.player.modeTimer = 0; }
      if (e.code === 'KeyC') { setPlayerMode(PlayerMode.CAR); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyJ') { setPlayerMode(PlayerMode.JET); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
        const aliveAllies = engineRef.current.allies.filter(a => !a.isDead).length;
        const titanMax = 100 + (aliveAllies * 100);
        setMaxHealth(titanMax);
        setHealth(titanMax);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      // Particle update
      for (let i = e.particles.length - 1; i >= 0; i--) {
        const p = e.particles[i];
        p.x += p.vx; p.y += p.vy; p.life--;
        if (p.life <= 0) e.particles.splice(i, 1);
      }

      if (e.cinematic) {
        Object.keys(keys).forEach(k => keys[k] = false);
        player.vel.x = 0;
        player.vel.y += GRAVITY;
      }

      if (currentMode !== PlayerMode.ROBOT && !e.cinematic) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
          const normalMax = 100 + (upgrades.robotTier * 50);
          setMaxHealth(normalMax);
          setHealth(h => Math.min(h, normalMax));
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (!e.cinematic) {
        if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = speed; player.facing = 1; } 
        else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -speed; player.facing = -1; } 
        else { player.vel.x *= 0.8; }

        if (currentMode === PlayerMode.JET) {
          if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -speed;
          else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = speed;
          else player.vel.y *= 0.8;
          player.grounded = false;
        } else {
          if ((keys['ArrowUp'] || keys['KeyW'] || (keys['Space'] && currentMode !== PlayerMode.JET)) && player.grounded) {
            player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
            player.grounded = false;
          }
          player.vel.y += GRAVITY;
        }
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) ? 24 : (currentMode === PlayerMode.TITAN ? 84 : 48);

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }

      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      allies.forEach((ally) => {
        if (ally.isDead) return;
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      // Combat Logic
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 10 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      if (!e.cinematic && keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = (currentMode === PlayerMode.TITAN) ? 30 : ((currentMode === PlayerMode.JET) ? 10 : ((currentMode === PlayerMode.CAR) ? 20 : 15));
        soundService.playShoot();
        bullets.push({
          pos: { x: player.pos.x + (player.facing === 1 ? 32 : 0), y: player.pos.y + shotYOffset },
          vel: { x: player.facing * 14, y: 0 },
          width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
        });
        allies.forEach(ally => {
          if (ally.isDead) return;
          bullets.push({
            pos: { x: ally.pos.x + (player.facing === 1 ? 32 : 0), y: ally.pos.y + 15 },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 15
          });
        });
        player.lastShot = e.frame;
      }

      // Physics: Bullets
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      // Physics: Enemies and Scripted Sequences
      let currentKills = 0;
      for (let i = 0; i < enemies.length; i++) {
        const enemy = enemies[i];
        if (enemy.isDead) { currentKills++; continue; }

        // Level 20 Dark Alpha Scripted Sequence
        if (enemy.type === 'dark_alpha' && enemy.health <= 0) {
          if (!e.cinematic) {
            e.cinematic = true;
            setIsCinematic(true);
            setCinematicText("ROGUE ALPHA CRITICAL. INITIATING LAST STRIKE.");
            enemy.sequenceStage = 1;
            enemy.sequenceTimer = 60;
            enemy.health = 1;
          }

          enemy.sequenceTimer!--;
          if (enemy.sequenceStage === 1 && enemy.sequenceTimer! <= 0) {
             const targetAlly = allies.find(a => !a.isDead);
             if (targetAlly) {
                const dx = targetAlly.pos.x - enemy.pos.x;
                enemy.pos.x += Math.sign(dx) * 15;
                if (Math.abs(dx) < 25) {
                   // Visual Smash at head
                   targetAlly.health = 0;
                   targetAlly.isDead = true;
                   soundService.playLose();
                   for (let p=0; p<15; p++) {
                      e.particles.push({x: targetAlly.pos.x+16, y: targetAlly.pos.y+10, vx: (Math.random()-0.5)*10, vy: (Math.random()-0.5)*10, life: 30, color: 'white'});
                   }
                   setCinematicText("SQUAD MEMBER DOWN! INITIATING REVENGE BARRAGE!");
                   enemy.sequenceStage = 2;
                   enemy.sequenceTimer = 30;
                }
             } else {
                enemy.sequenceStage = 2;
                enemy.sequenceTimer = 30;
                setCinematicText("INITIATING FINAL REVENGE!");
             }
          } else if (enemy.sequenceStage === 2 && enemy.sequenceTimer! <= 0) {
             // Revenge Fire from ALL survivors
             if (e.frame % 2 === 0) {
                soundService.playShoot();
                // Player shoots
                bullets.push({
                  pos: { x: player.pos.x+16, y: player.pos.y+24 },
                  vel: { x: (enemy.pos.x - player.pos.x) / 12, y: (enemy.pos.y - player.pos.y) / 12 },
                  width: 12, height: 12, owner: 'player', health: 1, maxHealth: 1, damage: 30,
                });
                // Allies shoot
                allies.forEach(a => {
                   if (!a.isDead) {
                      bullets.push({
                        pos: { x: a.pos.x+16, y: a.pos.y+24 },
                        vel: { x: (enemy.pos.x - a.pos.x) / 12, y: (enemy.pos.y - a.pos.y) / 12 },
                        width: 12, height: 12, owner: 'player', health: 1, maxHealth: 1, damage: 20,
                      });
                   }
                });
                enemy.health -= 60; 
                for (let p=0; p<2; p++) e.particles.push({x: enemy.pos.x+16, y: enemy.pos.y+24, vx: (Math.random()-0.5)*15, vy: (Math.random()-0.5)*15, life: 20, color: 'orange'});
             }
             if (enemy.health < -1000) {
                enemy.isDead = true;
                soundService.playVictory();
                setCinematicText("ALPHA DESTROYED. THE WAR IS OVER.");
                setTimeout(() => onWin(), 3000);
             }
          }
          continue; 
        }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;
          if (enemy.pos.y < floorY - enemy.height) {
            enemy.vel.y += GRAVITY;
            enemy.pos.y += enemy.vel.y;
          } else {
            enemy.pos.y = floorY - enemy.height;
            enemy.vel.y = 0;
          }
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'dark_alpha';
        const attackRange = 500;
        if (!e.cinematic && Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > 60) {
          bullets.push({
            pos: { x: enemy.pos.x, y: enemy.pos.y + 15 },
            vel: { x: Math.sign(player.pos.x - enemy.pos.x) * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 10
          });
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !e.cinematic) {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0 && enemy.type !== 'dark_alpha') enemy.isDead = true;
            }
          }
        });
      }

      if (!e.cinematic && health <= 0) onDie();

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);

      allies.forEach(ally => {
        if (ally.isDead) return;
        ctx.fillStyle = ally.color;
        ctx.fillRect(ally.pos.x - cameraX, ally.pos.y, 32, 48);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.strokeRect(ally.pos.x - cameraX, ally.pos.y, 32, 48);
      });

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        ctx.fillStyle = enemy.type === 'dark_alpha' ? '#222' : '#ff0055';
        ctx.fillRect(enemy.pos.x - cameraX, enemy.pos.y, enemy.width, enemy.height);
        if (enemy.type === 'dark_alpha') {
          ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 1; ctx.strokeRect(enemy.pos.x-cameraX, enemy.pos.y, enemy.width, enemy.height);
          ctx.fillStyle = '#f00'; ctx.fillRect(enemy.pos.x-cameraX + 8, enemy.pos.y + 8, 16, 4);
        }
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.fillStyle = SQUAD_COLORS[0];
      let pWidth = (e.mode === PlayerMode.TITAN) ? 64 : 32;
      let pHeight = (e.mode === PlayerMode.TITAN) ? 84 : 48;
      ctx.fillRect(player.pos.x - cameraX, player.pos.y, pWidth, pHeight);
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? '#00f3ff' : '#ff0055';
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
      });

      // Draw particles
      e.particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - cameraX, p.y, 3, 3);
      });

      if (e.cinematic) {
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(0, 0, CANVAS_WIDTH, 70);
        ctx.fillRect(0, CANVAS_HEIGHT - 70, CANVAS_WIDTH, 70);
      }
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      {!isCinematic && (
        <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
          <div className="flex flex-col gap-2">
            <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
              <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
                <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
                <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
              </div>
              <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
                <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
              </div>
            </div>
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30 uppercase">SECTOR {level}</div>
        </div>
      )}

      {isCinematic && (
        <div className="absolute top-1/4 w-full text-center z-50 animate-pulse pointer-events-none px-12">
           <div className="text-red-500 font-black text-3xl italic tracking-tighter uppercase font-orbitron drop-shadow-[0_0_10px_red]">{cinematicText}</div>
        </div>
      )}

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video bg-black rounded-lg shadow-2xl"/>
    </div>
  );
};

