import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 12; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; 
const MODE_DURATION_FRAMES = 30 * 60; 
const LEVEL_5_DISTANCE = 4000; 

const SQUAD_COLORS = ['#ff0000', '#111111', '#00ff00', '#ffffff', '#0000ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [kills, setKills] = useState(0);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);
  const [isCinematic, setIsCinematic] = useState(false);
  const [cinematicText, setCinematicText] = useState("");

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      lastAllyShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean; sequenceStage?: number; sequenceTimer?: number })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string; health: number; maxHealth: number; isDead: boolean }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level,
    cinematic: false,
    particles: [] as {x: number, y: number, vx: number, vy: number, life: number, color: string}[]
  });

  useEffect(() => {
    engineRef.current.isPaused = isPaused;
  }, [isPaused]);

  useEffect(() => {
    engineRef.current.mode = playerMode;
  }, [playerMode]);

  useEffect(() => {
    engineRef.current.level = level;
  }, [level]);

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.modeTimer = 0;
    e.player.lastAllyShot = 0;
    e.bullets = [];
    e.cameraX = 0;
    e.cinematic = false;
    e.particles = [];
    setIsCinematic(false);
    setCinematicText("");
    setKills(0);
    setDistance(0);
    setModeFramesLeft(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 350 + 48 - 48 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1],
          health: 100,
          maxHealth: 100,
          isDead: false
        });
      }
    }

    const enemies: (Enemy & { hasSplit?: boolean; sequenceStage?: number; sequenceTimer?: number })[] = [];
    const floorY = 350 + 48;

    if (level === 5) {
      enemies.push({
        id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80,
        health: 1200, maxHealth: 1200, isDead: false, type: 'tank', lastShot: 0
      });
      for (let i = 1; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1200 + i * 700, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
          health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({ 
        id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 600, maxHealth: 600, isDead: false, type: 'titan', lastShot: 0
      });
    } else if (level === 20) {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 1400 + i * 300, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 4, y: 0 }, 
          width: 32, height: 48, health: 150, maxHealth: 150, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48,
        health: 400, maxHealth: 400, isDead: false, type: 'dark_alpha', lastShot: 0,
        sequenceStage: 0, sequenceTimer: 0
      });
    } else {
      for (let i = 0; i < 4; i++) {
        enemies.push({
          id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 },
          width: 32, height: 48, health: 50 + level * 8, maxHealth: 50 + level * 8, isDead: false, type: 'bot', lastShot: 0
        });
      }
      enemies.push({
        id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96,
        health: 250 + level * 25, maxHealth: 250 + level * 25, isDead: false, type: 'titan', lastShot: 0
      });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (engineRef.current.cinematic) return;
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') { setPlayerMode(PlayerMode.ROBOT); engineRef.current.player.modeTimer = 0; }
      if (e.code === 'KeyC') { setPlayerMode(PlayerMode.CAR); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyJ') { setPlayerMode(PlayerMode.JET); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
        const aliveAllies = engineRef.current.allies.filter(a => !a.isDead).length;
        const titanMax = 100 + (aliveAllies * 100);
        setMaxHealth(titanMax);
        setHealth(titanMax);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) {
        update();
      }
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, keys, enemies, bullets, allies, level: curLevel } = e;
      const currentMode = e.mode;
      e.frame++;

      // Particle update
      for (let i = e.particles.length - 1; i >= 0; i--) {
        const p = e.particles[i];
        p.x += p.vx; p.y += p.vy; p.life--;
        if (p.life <= 0) e.particles.splice(i, 1);
      }

      if (e.cinematic) {
        Object.keys(keys).forEach(k => keys[k] = false);
        player.vel.x = 0;
        player.vel.y += GRAVITY;
      }

      if (currentMode !== PlayerMode.ROBOT && !e.cinematic) {
        player.modeTimer--;
        if (e.frame % 10 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setModeFramesLeft(0);
          const normalMax = 100 + (upgrades.robotTier * 50);
          setMaxHealth(normalMax);
          setHealth(h => Math.min(h, normalMax));
        }
      }

      let speed = PLAYER_SPEED_ROBOT;
      if (currentMode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (currentMode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (currentMode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (!e.cinematic) {
        if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = speed; player.facing = 1; } 
        else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -speed; player.facing = -1; } 
        else { player.vel.x *= 0.8; }

        if (currentMode === PlayerMode.JET) {
          if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -speed;
          else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = speed;
          else player.vel.y *= 0.8;
          player.grounded = false;
        } else {
          if ((keys['ArrowUp'] || keys['KeyW'] || (keys['Space'] && currentMode !== PlayerMode.JET)) && player.grounded) {
            player.vel.y = currentMode === PlayerMode.TITAN ? TITAN_JUMP_FORCE : JUMP_FORCE;
            player.grounded = false;
          }
          player.vel.y += GRAVITY;
        }
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 350 + 48;
      let effectiveHeight = (currentMode === PlayerMode.CAR || currentMode === PlayerMode.JET) ? 24 : (currentMode === PlayerMode.TITAN ? 84 : 48);

      if (player.pos.y > floorY - effectiveHeight) {
        player.pos.y = floorY - effectiveHeight;
        player.vel.y = 0;
        player.grounded = true;
      }

      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      allies.forEach((ally) => {
        if (ally.isDead) return;
        const targetX = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (targetX - ally.pos.x) * 0.1;
        ally.pos.y = floorY - 48; 
      });

      // Combat Logic
      const fireRate = Math.max(5, (currentMode === PlayerMode.JET ? 10 : (currentMode === PlayerMode.TITAN ? 22 : 12)) - (upgrades.weaponTier * 3));
      if (!e.cinematic && keys['Space'] && e.frame - player.lastShot > fireRate) {
        let shotYOffset = (currentMode === PlayerMode.TITAN) ? 30 : ((currentMode === PlayerMode.JET) ? 10 : ((currentMode === PlayerMode.CAR) ? 20 : 15));
        soundService.playShoot();
        bullets.push({
          pos: { x: player.pos.x + (player.facing === 1 ? 32 : 0), y: player.pos.y + shotYOffset },
          vel: { x: player.facing * 14, y: 0 },
          width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30
        });
        allies.forEach(ally => {
          if (ally.isDead) return;
          bullets.push({
            pos: { x: ally.pos.x + (player.facing === 1 ? 32 : 0), y: ally.pos.y + 15 },
            vel: { x: player.facing * 14, y: 0 },
            width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 15
          });
        });
        player.lastShot = e.frame;
      }

      // Physics: Bullets
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        b.pos.x += b.vel.x;
        b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      // Physics: Enemies and Scripted Sequences
      let currentKills = 0;
      for (let i = 0; i < enemies.length; i++) {
        const enemy = enemies[i];
        if (enemy.isDead) { currentKills++; continue; }

        // Level 20 Dark Alpha Scripted Sequence
        if (enemy.type === 'dark_alpha' && enemy.health <= 0) {
          if (!e.cinematic) {
            e.cinematic = true;
            setIsCinematic(true);
            setCinematicText("ROGUE ALPHA CRITICAL. INITIATING LAST STRIKE.");
            enemy.sequenceStage = 1;
            enemy.sequenceTimer = 40; // Reduced to ~0.6s for snappier intro
            enemy.health = 1;
          }

          enemy.sequenceTimer!--;
          if (enemy.sequenceStage === 1 && enemy.sequenceTimer! <= 0) {
             const targetAlly = allies.find(a => !a.isDead);
             if (targetAlly) {
                const dx = targetAlly.pos.x - enemy.pos.x;
                enemy.pos.x += Math.sign(dx) * 20; // Faster dash
                if (Math.abs(dx) < 25) {
                   // Visual Smash at head
                   targetAlly.health = 0;
                   targetAlly.isDead = true;
                   soundService.playLose();
                   for (let p=0; p<15; p++) {
                      e.particles.push({x: targetAlly.pos.x+16, y: targetAlly.pos.y+10, vx: (Math.random()-0.5)*10, vy: (Math.random()-0.5)*10, life: 30, color: 'white'});
                   }
                   setCinematicText("SQUAD MEMBER DOWN! INITIATING REVENGE BARRAGE!");
                   enemy.sequenceStage = 2;
                   enemy.sequenceTimer = 25; // 0.4s pause after smash
                }
             } else {
                enemy.sequenceStage = 2;
                enemy.sequenceTimer = 25;
                setCinematicText("INITIATING FINAL REVENGE!");
             }
          } else if (enemy.sequenceStage === 2 && enemy.sequenceTimer! <= 0) {
             // Revenge Fire from ALL survivors
             if (e.frame % 2 === 0) {
                soundService.playShoot();
                // Player shoots
                bullets.push({
                  pos: { x: player.pos.x+16, y: player.pos.y+24 },
                  vel: { x: (enemy.pos.x - player.pos.x) / 10, y: (enemy.pos.y - player.pos.y) / 10 },
                  width: 12, height: 12, owner: 'player', health: 1, maxHealth: 1, damage: 30,
                });
                // Allies shoot
                allies.forEach(a => {
                   if (!a.isDead) {
                      bullets.push({
                        pos: { x: a.pos.x+16, y: a.pos.y+24 },
                        vel: { x: (enemy.pos.x - a.pos.x) / 10, y: (enemy.pos.y - a.pos.y) / 10 },
                        width: 12, height: 12, owner: 'player', health: 1, maxHealth: 1, damage: 20,
                      });
                   }
                });
                enemy.health -= 70; 
                for (let p=0; p<2; p++) e.particles.push({x: enemy.pos.x+16, y: enemy.pos.y+24, vx: (Math.random()-0.5)*15, vy: (Math.random()-0.5)*15, life: 20, color: 'orange'});
             }
             if (enemy.health < -1000) {
                enemy.isDead = true;
                soundService.playVictory();
                setCinematicText("ALPHA DESTROYED. THE WAR IS OVER.");
                setTimeout(() => onWin(), 3000);
             }
          }
          continue; 
        }

        if (enemy.type === 'tank') {
          enemy.pos.x += enemy.vel.x;
        } else {
          enemy.pos.x += enemy.vel.x;
          if (Math.random() < 0.015) enemy.vel.x *= -1;
          if (enemy.pos.y < floorY - enemy.height) {
            enemy.vel.y += GRAVITY;
            enemy.pos.y += enemy.vel.y;
          } else {
            enemy.pos.y = floorY - enemy.height;
            enemy.vel.y = 0;
          }
        }

        const isBossUnit = enemy.type === 'titan' || enemy.type === 'tank' || enemy.type === 'dark_alpha';
        const attackRange = 500;
        if (!e.cinematic && Math.abs(enemy.pos.x - player.pos.x) < attackRange && e.frame - enemy.lastShot > 60) {
          bullets.push({
            pos: { x: enemy.pos.x, y: enemy.pos.y + 15 },
            vel: { x: Math.sign(player.pos.x - enemy.pos.x) * 6, y: 0 }, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 10
          });
          enemy.lastShot = e.frame;
        }

        bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !e.cinematic) {
            if (b.pos.x < enemy.pos.x + enemy.width && b.pos.x + b.width > enemy.pos.x &&
                b.pos.y < enemy.pos.y + enemy.height && b.pos.y + b.height > enemy.pos.y) {
              enemy.health -= b.damage || 25;
              bullets.splice(bIdx, 1);
              if (enemy.health <= 0 && enemy.type !== 'dark_alpha') enemy.isDead = true;
            }
          }
        });
      }

      if (!e.cinematic && health <= 0) onDie();

      e.cameraX = player.pos.x - CANVAS_WIDTH / 3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const e = engineRef.current;
      const { player, enemies, bullets, allies, cameraX } = e;

      ctx.fillStyle = '#050510';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      const floorY = 350 + 48;
      ctx.fillStyle = '#1c1c1c';
      ctx.fillRect(0, floorY, CANVAS_WIDTH, CANVAS_HEIGHT - floorY);

      allies.forEach(ally => {
        if (ally.isDead) return;
        ctx.fillStyle = ally.color;
        ctx.fillRect(ally.pos.x - cameraX, ally.pos.y, 32, 48);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.strokeRect(ally.pos.x - cameraX, ally.pos.y, 32, 48);
      });

      enemies.forEach(enemy => {
        if (enemy.isDead) return;
        ctx.fillStyle = enemy.type === 'dark_alpha' ? '#222' : '#ff0055';
        ctx.fillRect(enemy.pos.x - cameraX, enemy.pos.y, enemy.width, enemy.height);
        if (enemy.type === 'dark_alpha') {
          ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 1; ctx.strokeRect(enemy.pos.x-cameraX, enemy.pos.y, enemy.width, enemy.height);
          ctx.fillStyle = '#f00'; ctx.fillRect(enemy.pos.x-cameraX + 8, enemy.pos.y + 8, 16, 4);
        }
      });

      ctx.save();
      if (player.invulnerable > 0 && e.frame % 4 < 2) ctx.globalAlpha = 0.5;
      ctx.fillStyle = SQUAD_COLORS[0];
      let pWidth = (e.mode === PlayerMode.TITAN) ? 64 : 32;
      let pHeight = (e.mode === PlayerMode.TITAN) ? 84 : 48;
      ctx.fillRect(player.pos.x - cameraX, player.pos.y, pWidth, pHeight);
      ctx.restore();

      bullets.forEach(b => {
        ctx.fillStyle = b.owner === 'player' ? '#00f3ff' : '#ff0055';
        ctx.fillRect(b.pos.x - cameraX, b.pos.y, b.width, b.height);
      });

      // Draw particles
      e.particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - cameraX, p.y, 3, 3);
      });

      if (e.cinematic) {
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(0, 0, CANVAS_WIDTH, 70);
        ctx.fillRect(0, CANVAS_HEIGHT - 70, CANVAS_WIDTH, 70);
      }
    };

    loop();
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      cancelAnimationFrame(animationId);
    };
  }, [resetLevel, onDie, onWin, level, upgrades]);

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center bg-black">
      {!isCinematic && (
        <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none z-10">
          <div className="flex flex-col gap-2">
            <div className="bg-black/70 border border-cyan-900 p-2 rounded backdrop-blur-sm shadow-[0_0_15px_rgba(0,0,0,0.5)]">
              <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
                <span className="tracking-tighter font-orbitron">HULL INTEGRITY</span>
                <span className="font-mono">{Math.round(health)}/{maxHealth}</span>
              </div>
              <div className="w-56 h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
                <div className="h-full bg-gradient-to-r from-red-700 via-cyan-500 to-blue-400 transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
              </div>
            </div>
          </div>
          <div className="text-white font-black text-2xl font-orbitron tracking-tighter italic bg-blue-900/20 px-3 py-1 border border-blue-500/30 uppercase">SECTOR {level}</div>
        </div>
      )}

      {isCinematic && (
        <div className="absolute top-1/4 w-full text-center z-50 animate-pulse pointer-events-none px-12">
           <div className="text-red-500 font-black text-3xl italic tracking-tighter uppercase font-orbitron drop-shadow-[0_0_10px_red]">{cinematicText}</div>
        </div>
      )}

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="neon-border max-w-full aspect-video bg-black rounded-lg shadow-2xl"/>
    </div>
  );
};

export default GameView;

import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

async function callGeminiWithRetry(level: number, specialPrompt: string, retries = 2): Promise<any> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short cyberpunk mission briefing for Level ${level} of a robot police officer game. 
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the threat in the burning city.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error: any) {
    if (retries > 0 && (error?.status === 429 || error?.message?.includes('429'))) {
      console.warn(`Gemini 429 encountered. Retrying in ${3 - retries}s...`);
      await delay(1000 * (3 - retries));
      return callGeminiWithRetry(level, specialPrompt, retries - 1);
    }
    throw error;
  }
}

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "This is an escape mission! The player must run away from a giant shooting tank across a burning city.";
  if (level === 20) specialPrompt = "This is the final showdown against the dark gray Alpha Enforcer. It is smaller but more lethal than other bosses. Foreshadow a high personal cost for victory.";

  try {
    return await callGeminiWithRetry(level, specialPrompt);
  } catch (error) {
    console.error("Gemini failed, using fallback briefing", error);
    return {
      level,
      title: level === 20 ? "The Final Enforcer" : (level === 5 ? "Death Chase" : `Sector ${level} Purge`),
      description: level === 5 
        ? "A massive siege tank is pursuing you. Reach the extraction point before you are pulverized." 
        : (level === 20 ? "The Rogue Alpha has been cornered. Neutralize the dark gray enforcer to end the war, but be prepared for its desperate final struggle." : "Hostile units detected in the burning sector. Cleanse the area."),
      threatLevel: level >= 15 ? "Extreme" : "High",
      enemyType: level === 5 ? "Siege Tank" : (level === 20 ? "Dark Alpha Enforcer" : "Rogue Battalion")
    };
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { PlayerMode, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const PLAYER_SPEED_ROBOT = 4;
const PLAYER_SPEED_CAR = 10;
const PLAYER_SPEED_JET = 12; 
const PLAYER_SPEED_TITAN = 3.5; 
const JUMP_FORCE = -11;
const TITAN_JUMP_FORCE = -13;
const TITAN_DURATION_FRAMES = 60 * 60; 
const MODE_DURATION_FRAMES = 30 * 60; 

const SQUAD_COLORS = ['#ff3333', '#222222', '#33ff33', '#eeeeee', '#3333ff'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [playerMode, setPlayerMode] = useState<PlayerMode>(PlayerMode.ROBOT);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [modeFramesLeft, setModeFramesLeft] = useState(0);
  const [distance, setDistance] = useState(0);
  const [isCinematic, setIsCinematic] = useState(false);
  const [cinematicText, setCinematicText] = useState("");

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      modeTimer: 0
    },
    enemies: [] as (Enemy & { hasSplit?: boolean; sequenceStage?: number; sequenceTimer?: number })[],
    bullets: [] as (Bullet & { damage?: number })[],
    allies: [] as { pos: { x: number; y: number }; offset: { x: number; y: number }; color: string; health: number; maxHealth: number; isDead: boolean }[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    mode: PlayerMode.ROBOT,
    level: level,
    cinematic: false,
    particles: [] as {x: number, y: number, vx: number, vy: number, life: number, color: string, size: number}[]
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.mode = playerMode; }, [playerMode]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  // Realistic Procedural Drawing
  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawRobot = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, facing: number, frame: number, isEnemy = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;

    // Torso
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    // Head
    drawMechanicalPart(ctx, -8, -30, 16, 12, '#333', 6);
    // Optical Sensor
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff';
    ctx.beginPath();
    ctx.arc(4, -24, 2, 0, Math.PI * 2);
    ctx.fill();
    if (Math.sin(frame * 0.1) > 0.8) {
      ctx.shadowBlur = 10;
      ctx.shadowColor = ctx.fillStyle as string;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Legs
    drawMechanicalPart(ctx, -10, 10, 8, 14 + legSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 2, 10, 8, 14 - legSwing/2, '#222', 2);

    // Arm (Weapon)
    drawMechanicalPart(ctx, 4, -10, 18, 8, '#444', 2);

    ctx.restore();
  };

  const drawCar = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, facing: number, frame: number) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    // Body
    drawMechanicalPart(ctx, -24, -4, 48, 16, color, 8);
    drawMechanicalPart(ctx, -12, -14, 24, 12, '#111', 10); // Cab

    // Wheels
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(-15, 12, 6, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(15, 12, 6, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#444';
    ctx.beginPath(); ctx.arc(-15, 12, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(15, 12, 2, 0, Math.PI * 2); ctx.fill();

    // Lights
    ctx.fillStyle = '#00f3ff';
    ctx.fillRect(18, -2, 4, 4);

    ctx.restore();
  };

  const drawJet = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, facing: number, frame: number) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    // Fuselage
    drawMechanicalPart(ctx, -24, -4, 48, 8, color, 2);
    // Cockpit
    drawMechanicalPart(ctx, 0, -8, 16, 6, '#00f3ff44', 10);
    // Wings
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(-20, -12); ctx.lineTo(5, 0); ctx.closePath();
    ctx.fillStyle = color; ctx.fill();

    // Thrusters
    ctx.fillStyle = '#ff6600';
    if (frame % 4 < 2) ctx.fillRect(-30, -2, 8, 4);

    ctx.restore();
  };

  const drawTitan = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, frame: number) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);

    const hue = frame % 360;
    const color = `hsl(${hue}, 70%, 50%)`;

    // Massive Legs
    drawMechanicalPart(ctx, -28, 10, 20, 34, '#111', 4);
    drawMechanicalPart(ctx, 8, 10, 20, 34, '#111', 4);

    // Core
    drawMechanicalPart(ctx, -32, -30, 64, 50, color, 12);
    drawMechanicalPart(ctx, -20, -20, 40, 30, '#000', 8); // Core glow slot
    ctx.shadowBlur = 15; ctx.shadowColor = '#00f3ff';
    ctx.fillStyle = '#00f3ff'; ctx.fillRect(-15, -15, 30, 20);
    ctx.shadowBlur = 0;

    // Head
    drawMechanicalPart(ctx, -12, -45, 24, 18, '#222', 10);
    ctx.fillStyle = '#00f3ff'; ctx.fillRect(-8, -40, 16, 4);

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const calcMaxHealth = 100 + (upgrades.robotTier * 50);
    e.player.maxHealth = calcMaxHealth;
    setMaxHealth(calcMaxHealth);
    setHealth(calcMaxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    e.cinematic = false;
    e.particles = [];
    setIsCinematic(false);
    setCinematicText("");
    setDistance(0);
    setPlayerMode(PlayerMode.ROBOT);

    e.allies = [];
    if (level >= 2) {
      for (let i = 0; i < 4; i++) {
        e.allies.push({
          pos: { x: 100, y: 398 },
          offset: { x: -80 - i * 60, y: 0 },
          color: SQUAD_COLORS[i + 1],
          health: 100, maxHealth: 100, isDead: false
        });
      }
    }

    const enemies: any[] = [];
    const floorY = 398;

    if (level === 5) {
      enemies.push({ id: 0, pos: { x: -600, y: floorY - 80 }, vel: { x: 5.2, y: 0 }, width: 150, height: 80, health: 1500, maxHealth: 1500, isDead: false, type: 'tank', lastShot: 0 });
      for (let i = 1; i < 4; i++) enemies.push({ id: i, pos: { x: 1200 + i * 500, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, health: 80, maxHealth: 80, isDead: false, type: 'bot', lastShot: 0 });
      enemies.push({ id: 4, pos: { x: 4500, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96, health: 800, maxHealth: 800, isDead: false, type: 'titan', lastShot: 0 });
    } else if (level === 20) {
      for (let i = 0; i < 4; i++) enemies.push({ id: i, pos: { x: 1400 + i * 300, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 4, y: 0 }, width: 32, height: 48, health: 200, maxHealth: 200, isDead: false, type: 'bot', lastShot: 0 });
      enemies.push({ id: 4, pos: { x: 3000, y: floorY - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, health: 400, maxHealth: 400, isDead: false, type: 'dark_alpha', lastShot: 0, sequenceStage: 0, sequenceTimer: 0 });
    } else {
      for (let i = 0; i < 4; i++) enemies.push({ id: i, pos: { x: 800 + i * 550, y: floorY - 48 }, vel: { x: (Math.random() - 0.5) * 2.5, y: 0 }, width: 32, height: 48, health: 50 + level * 10, maxHealth: 50 + level * 10, isDead: false, type: 'bot', lastShot: 0 });
      enemies.push({ id: 4, pos: { x: 3000, y: floorY - 96 }, vel: { x: 0, y: 0 }, width: 64, height: 96, health: 300 + level * 20, maxHealth: 300 + level * 20, isDead: false, type: 'titan', lastShot: 0 });
    }
    e.enemies = enemies;
  }, [level, upgrades]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      if (engineRef.current.cinematic) return;
      engineRef.current.keys[e.code] = true;
      if (e.code === 'KeyR') { setPlayerMode(PlayerMode.ROBOT); engineRef.current.player.modeTimer = 0; }
      if (e.code === 'KeyC') { setPlayerMode(PlayerMode.CAR); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyJ') { setPlayerMode(PlayerMode.JET); engineRef.current.player.modeTimer = MODE_DURATION_FRAMES; }
      if (e.code === 'KeyK' && level >= 2) {
        setPlayerMode(PlayerMode.TITAN);
        engineRef.current.player.modeTimer = TITAN_DURATION_FRAMES;
        setHealth(engineRef.current.player.maxHealth + 400); // Titan boost
        setMaxHealth(engineRef.current.player.maxHealth + 400);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, allies, keys } = e;
      e.frame++;

      // Transformation logic
      if (e.mode !== PlayerMode.ROBOT && !e.cinematic) {
        player.modeTimer--;
        if (e.frame % 15 === 0) setModeFramesLeft(player.modeTimer);
        if (player.modeTimer <= 0) {
          setPlayerMode(PlayerMode.ROBOT);
          setMaxHealth(100 + upgrades.robotTier * 50);
          setHealth(h => Math.min(h, 100 + upgrades.robotTier * 50));
        }
      }

      // Movement
      let speed = PLAYER_SPEED_ROBOT;
      if (e.mode === PlayerMode.CAR) speed = PLAYER_SPEED_CAR;
      if (e.mode === PlayerMode.JET) speed = PLAYER_SPEED_JET;
      if (e.mode === PlayerMode.TITAN) speed = PLAYER_SPEED_TITAN;

      if (!e.cinematic) {
        if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = speed; player.facing = 1; if (e.mode === PlayerMode.CAR) soundService.playDrive(1); }
        else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -speed; player.facing = -1; if (e.mode === PlayerMode.CAR) soundService.playDrive(1); }
        else { player.vel.x *= 0.8; }

        if (e.mode === PlayerMode.JET) {
          if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -speed;
          else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = speed;
          else player.vel.y *= 0.8;
          player.grounded = false;
          soundService.playFly();
        } else {
          if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
            player.vel.y = (e.mode === PlayerMode.TITAN) ? TITAN_JUMP_FORCE : JUMP_FORCE;
            player.grounded = false;
          }
          player.vel.y += GRAVITY;
        }
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      const h = (e.mode === PlayerMode.TITAN) ? 84 : 48;
      if (player.pos.y > floorY - h) { player.pos.y = floorY - h; player.vel.y = 0; player.grounded = true; }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Ally movement
      allies.forEach(ally => {
        if (ally.isDead) return;
        const tx = player.pos.x + (player.facing === 1 ? ally.offset.x : -ally.offset.x - 32);
        ally.pos.x += (tx - ally.pos.x) * 0.15;
        ally.pos.y = floorY - 48;
      });

      // Weapons
      const fr = Math.max(5, (e.mode === PlayerMode.JET ? 10 : 15) - upgrades.weaponTier * 3);
      if (!e.cinematic && keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        bullets.push({ pos: { x: player.pos.x + (player.facing === 1 ? 32 : 0), y: player.pos.y + 15 }, vel: { x: player.facing * 15, y: 0 }, width: 10, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 30 });
        allies.forEach(a => { if(!a.isDead) bullets.push({ pos: { x: a.pos.x + 16, y: a.pos.y + 15 }, vel: { x: player.facing * 15, y: 0 }, width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 15 }); });
        player.lastShot = e.frame;
      }

      // Bullets update
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      // Enemy logic
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        // Scripted Sequences (Dark Alpha)
        if (en.type === 'dark_alpha' && en.health <= 0) {
           if (!e.cinematic) { e.cinematic = true; setIsCinematic(true); setCinematicText("ROGUE ALPHA CRITICAL. INITIATING LAST STRIKE."); en.sequenceStage = 1; en.sequenceTimer = 40; en.health = 1; }
           en.sequenceTimer!--;
           if (en.sequenceStage === 1 && en.sequenceTimer! <= 0) {
              const target = allies.find(a => !a.isDead) || player;
              en.pos.x += Math.sign(target.pos.x - en.pos.x) * 20;
              if (Math.abs(target.pos.x - en.pos.x) < 20) {
                if ('isDead' in target) { target.isDead = true; soundService.playLose(); } else { setHealth(h => h - 50); }
                setCinematicText("SQUAD MEMBER DOWN! REVENGE PROTOCOL ACTIVE!");
                en.sequenceStage = 2; en.sequenceTimer = 30;
              }
           } else if (en.sequenceStage === 2 && en.sequenceTimer! <= 0) {
              if (e.frame % 3 === 0) {
                soundService.playShoot();
                bullets.push({ pos: {x: player.pos.x + 16, y: player.pos.y + 24}, vel: {x: (en.pos.x - player.pos.x)/10, y: (en.pos.y - player.pos.y)/10}, width: 12, height: 12, owner: 'player', health: 1, maxHealth: 1, damage: 50 });
                en.health -= 80;
              }
              if (en.health < -1000) { en.isDead = true; soundService.playVictory(); setTimeout(() => onWin(), 2500); }
           }
           return;
        }

        // Standard movement
        if (en.type === 'tank') en.pos.x += en.vel.x;
        else { en.pos.x += en.vel.x; if (Math.random() < 0.02) en.vel.x *= -1; }

        // Combat
        if (!e.cinematic && Math.abs(en.pos.x - player.pos.x) < 500 && e.frame - en.lastShot > 80) {
          bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: Math.sign(player.pos.x - en.pos.x) * 5, y: 0}, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 10 });
          en.lastShot = e.frame;
        }

        // Bullet collision
        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; bullets.splice(idx, 1);
            if (en.health <= 0 && en.type !== 'dark_alpha') {
               en.isDead = true;
               if (en.type === 'titan' && !en.hasSplit) {
                 en.isDead = false; en.health = 100; en.hasSplit = true;
                 for (let k=0; k<6; k++) enemies.push({ id: Date.now()+k, pos: {x: en.pos.x, y: en.pos.y}, vel: {x: (Math.random()-0.5)*10, y: -5}, width: 32, height: 48, health: 50, maxHealth: 50, isDead: false, type: 'bot', lastShot: 0 });
                 en.isDead = true;
               }
            }
          }
        });

        // Player collision
        if (!e.cinematic && !player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + player.width > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + player.height > en.pos.y) {
           setHealth(h => h - 20); player.invulnerable = 60; soundService.playLose();
        }
      });

      if (!e.cinematic && health <= 0) onDie();
      if (!e.cinematic && allDead && level !== 5 && level !== 20) onWin();
      if (level === 5 && player.pos.x > 4000) onWin();

      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;

      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Parallax City (Placeholder logic for style)
      ctx.fillStyle = '#0a0a20';
      for (let i = 0; i < 10; i++) { ctx.fillRect((i * 200 - e.cameraX * 0.2) % 1000, 100, 150, 400); }

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.allies.forEach(a => { if(!a.isDead) drawRobot(ctx, a.pos.x - e.cameraX, a.pos.y, 32, 48, a.color, e.player.facing, e.frame); });
      e.enemies.forEach(en => { if(!en.isDead) {
        if (en.type === 'dark_alpha') drawRobot(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, '#222', -1, e.frame, true);
        else if (en.type === 'titan') drawTitan(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, e.frame);
        else drawRobot(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, '#ff0055', -1, e.frame, true);
      }});

      if (e.mode === PlayerMode.ROBOT) drawRobot(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, 32, 48, SQUAD_COLORS[0], e.player.facing, e.frame);
      else if (e.mode === PlayerMode.CAR) drawCar(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, 48, 24, SQUAD_COLORS[0], e.player.facing, e.frame);
      else if (e.mode === PlayerMode.JET) drawJet(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, 48, 24, SQUAD_COLORS[0], e.player.facing, e.frame);
      else drawTitan(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, 64, 84, e.frame);

      e.bullets.forEach(b => { ctx.fillStyle = b.owner === 'player' ? '#00f3ff' : '#ff0055'; ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); });

      if (e.cinematic) {
        ctx.fillStyle = 'rgba(0,0,0,0.7)'; ctx.fillRect(0, 0, CANVAS_WIDTH, 80); ctx.fillRect(0, CANVAS_HEIGHT - 80, CANVAS_WIDTH, 80);
      }
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      {!isCinematic && (
        <div className="absolute top-4 left-4 z-10 space-y-2 pointer-events-none">
          <div className="bg-black/60 border border-cyan-500 p-3 rounded backdrop-blur">
            <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
              <span>HULL INTEGRITY</span>
              <span>{Math.round(health)}/{maxHealth}</span>
            </div>
            <div className="w-48 h-2 bg-gray-900 rounded-full overflow-hidden">
              <div className="h-full bg-cyan-500 shadow-[0_0_10px_cyan]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
            </div>
          </div>
          {playerMode !== PlayerMode.ROBOT && (
            <div className="bg-black/60 border border-yellow-500 p-2 rounded text-[10px] font-bold text-yellow-400">
              {playerMode} MODE: {Math.ceil(modeFramesLeft / 60)}s
            </div>
          )}
        </div>
      )}
      {isCinematic && (
        <div className="absolute top-1/4 w-full text-center z-20 pointer-events-none animate-pulse">
          <div className="text-red-500 font-black text-2xl italic tracking-tighter uppercase font-orbitron drop-shadow-[0_0_8px_red]">{cinematicText}</div>
        </div>
      )}
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
    </div>
  );
};

export default GameView;
